147	#[cfg(test)]
148	mod tests {
149	    use super::*;
150	    use crate::core::vrp::test_utils::{make_input, make_stop};
151	
152	    #[test]
153	    fn test_neural_selector_shape() {
154	        let stops = vec![
155	            make_stop(0.0, 0.0, "depot"),
156	            make_stop(1.0, 0.0, "a"),
157	            make_stop(0.0, 1.0, "b"),
158	        ];
159	        let input = make_input(stops, 1);
160	        let features = InstanceFeatures::from_input(&input);
161	        let vec = features.to_vector();
162	        assert_eq!(vec.len(), NUM_FEATURES);
163	    }
164	
165	    #[test]
166	    fn test_predict_solver_fallback() {
167	        let stops = vec![
168	            make_stop(0.0, 0.0, "depot"),
169	            make_stop(1.0, 0.0, "a"),
170	            make_stop(2.0, 0.0, "b"),
171	        ];
172	        let input = make_input(stops, 1);
173	        let pred = predict_solver(&input, Some(Path::new("/nonexistent/model.safetensors"))
174	        ).unwrap();
175	        assert!(!pred.recommended.is_empty());
176	        assert!(pred.confidence > 0.0);
177	    }
178	}

  1	//! Instance feature extraction for learned VRP models.
  2	//!
  3	//! Extracts a 28-dimensional feature vector from a VRP instance.
  4	//! Based on research:
  5	//!   - Instance-Aware Parameter Configuration (2605.00572, 2026)
  6	//!   - RouteFinder (2406.15007, 2024)
  7	//!   - RRNCO (2503.16159, 2025)
  8	
  9	use crate::core::haversine_m;
 10	use crate::core::vrp::types::{VRPSolverInput, VRPSolverStop, VrpObjective};
 11	use std::collections::HashMap;
 12	
 13	/// 28-dimensional normalized instance feature vector.
 14	#[derive(Debug, Clone, Default, serde::Serialize)]
 15	pub struct InstanceFeatures {
 16	    // Geometric (8)
 17	    pub n_stops_norm: f64,
 18	    pub n_vehicles_norm: f64,
 19	    pub avg_pairwise_km_norm: f64,
 20	    pub lat_spread_norm: f64,
 21	    pub lon_spread_norm: f64,
 22	    pub density_norm: f64,
 23	    pub area_km2_norm: f64,
 24	    pub depot_centroid_dist_norm: f64,
 25	
 26	    // Graph (8) — from kNN(k=10) graph of stops
 27	    pub knn_avg_degree: f64,
 28	    pub knn_max_degree: f64,
 29	    pub knn_clustering: f64,
 30	    pub knn_diameter_norm: f64,
 31	    pub knn_mst_weight_norm: f64,
 32	    pub knn_avg_shortest_path: f64,
 33	    pub knn_spectral_gap: f64,
 34	    pub knn_assortativity: f64,
 35	
 36	    // Demand (4)
 37	    pub total_demand_norm: f64,
 38	    pub demand_std_norm: f64,
 39	    pub tight_capacity_flag: f64,
 40	    pub capacity_ratio: f64,
 41	
 42	    // Distance matrix stats (4)
 43	    pub dist_mean_norm: f64,
 44	    pub dist_std_norm: f64,
 45	    pub dist_skewness: f64,
 46	    pub depot_dist_mean_norm: f64,
 47	
 48	    // Objective & interaction (4)
 49	    pub objective_min_distance: f64,
 50	    pub objective_min_time: f64,
 51	    pub objective_balance_load: f64,
 52	    pub objective_min_vehicles: f64,
 53	}
 54	
 55	impl InstanceFeatures {
 56	    /// Extract features from a VRP input. Depot is index 0.
 57	    pub fn from_input(input: &VRPSolverInput) -> Self {
 58	        let stops = &input.locations;
 59	        let n = stops.len();
 60	        if n <= 1 {
 61	            return Self::default();
 62	        }
 63	
 64	        let depot = &stops[0];
 65	        let others: Vec<&VRPSolverStop> = stops.iter().skip(1).collect();
 66	        let num_stops = others.len();
 67	
 68	        // ── Geometric features ──────────────────────────────────────────
 69	        let mut dists = Vec::new();
 70	        for (i, a) in others.iter().enumerate() {
 71	            for b in others.iter().skip(i + 1) {
 72	                dists.push(haversine_m(a.lat, a.lon, b.lat, b.lon) / 1000.0);
 73	            }
 74	        }
 75	        let avg_pairwise_km = if !dists.is_empty() {
 76	            dists.iter().sum::<f64>() / dists.len() as f64
 77	        } else {
 78	            0.0
 79	        };
 80	
 81	        let lats: Vec<f64> = others.iter().map(|s| s.lat).collect();
 82	        let lons: Vec<f64> = others.iter().map(|s| s.lon).collect();
 83	        let lat_spread = std_dev(&lats);
 84	        let lon_spread = std_dev(&lons);
 85	
 86	        let lat_km = lat_spread * 111.0;
 87	        let lon_km = lon_spread * 111.0 * depot.lat.to_radians().cos();
 88	        let area_km2 = (lat_km * lon_km).max(0.001);
 89	        let density = num_stops as f64 / area_km2;
 90	
 91	        // Centroid of stops
 92	        let centroid_lat = lats.iter().sum::<f64>() / lats.len() as f64;
 93	        let centroid_lon = lons.iter().sum::<f64>() / lons.len() as f64;
 94	        let depot_centroid_dist = haversine_m(depot.lat, depot.lon, centroid_lat, centroid_lon) / 1000.0;
 95	
 96	        // ── Demand features ───────────────────────────────────────────
 97	        let demands: Vec<f64> = others.iter().filter_map(|s| s.demand).collect();
 98	        let total_demand: f64 = demands.iter().sum();
 99	        let demand_std = std_dev(&demands);
100	        let capacity_ratio = if input.vehicle_capacity > 0.0 {
101	            total_demand / (input.vehicle_capacity * input.num_vehicles.max(1) as f64)
102	        } else {
103	            0.0
104	        };
105	        let tight_capacity = capacity_ratio > 0.8;
106	
107	        // ── Distance matrix stats ──────────────────────────────────────
108	        let depot_dists: Vec<f64> = others
109	            .iter()
110	            .map(|s| haversine_m(depot.lat, depot.lon, s.lat, s.lon) / 1000.0)
111	            .collect();
112	        let dist_mean = if !dists.is_empty() {
113	            dists.iter().sum::<f64>() / dists.len() as f64
114	        } else {
115	            0.0
116	        };
117	        let dist_std = std_dev(&dists);
118	        let dist_skew = skewness(&dists);
119	        let depot_dist_mean = if !depot_dists.is_empty() {
120	            depot_dists.iter().sum::<f64>() / depot_dists.len() as f64
121	        } else {
122	            0.0
123	        };
124	
125	        // ── kNN graph features (k=10) ──────────────────────────────────
126	        let knn_feats = knn_graph_features(&others, 10);
127	
128	        // ── Normalization constants (from training distribution) ───────
129	        // These are approximate; the real training distribution should be used.
130	        Self {
131	            n_stops_norm: (num_stops as f64 / 500.0).min(1.0),
132	            n_vehicles_norm: (input.num_vehicles.max(1) as f64 / 20.0).min(1.0),
133	            avg_pairwise_km_norm: (avg_pairwise_km / 100.0).min(1.0),
134	            lat_spread_norm: (lat_spread / 5.0).min(1.0),
135	            lon_spread_norm: (lon_spread / 5.0).min(1.0),
136	            density_norm: (density / 50.0).min(1.0),
137	            area_km2_norm: (area_km2 / 1000.0).min(1.0),
138	            depot_centroid_dist_norm: (depot_centroid_dist / 100.0).min(1.0),
139	
140	            knn_avg_degree: knn_feats.avg_degree,
141	            knn_max_degree: knn_feats.max_degree,
142	            knn_clustering: knn_feats.clustering,
143	            knn_diameter_norm: (knn_feats.diameter / 100.0).min(1.0),
144	            knn_mst_weight_norm: (knn_feats.mst_weight / 1000.0).min(1.0),
145	            knn_avg_shortest_path: (knn_feats.avg_shortest_path / 100.0).min(1.0),
146	            knn_spectral_gap: (knn_feats.spectral_gap / 50.0).min(1.0),
147	            knn_assortativity: knn_feats.assortativity.clamp(-1.0, 1.0),
148	
149	            total_demand_norm: (total_demand / 1000.0).min(1.0),
150	            demand_std_norm: (demand_std / 100.0).min(1.0),
151	            tight_capacity_flag: if tight_capacity { 1.0 } else { 0.0 },
152	            capacity_ratio: capacity_ratio.min(1.0),
153	
154	            dist_mean_norm: (dist_mean / 100.0).min(1.0),
155	            dist_std_norm: (dist_std / 100.0).min(1.0),
156	            dist_skewness: dist_skew,
157	            depot_dist_mean_norm: (depot_dist_mean / 100.0).min(1.0),
158	
159	            objective_min_distance: match input.objective {
160	                VrpObjective::MinDistance => 1.0,
161	                _ => 0.0,
162	            },
163	            objective_min_time: match input.objective {
164	                VrpObjective::MinTime => 1.0,
165	                _ => 0.0,
166	            },
167	            objective_balance_load: match input.objective {
168	                VrpObjective::BalanceLoad => 1.0,
169	                _ => 0.0,
170	            },
171	            objective_min_vehicles: match input.objective {
172	                VrpObjective::MinVehicles => 1.0,
173	                _ => 0.0,
174	            },
175	        }
176	    }
177	
178	    /// Flatten to a dense Vec<f32> for neural network input.
179	    pub fn to_vector(&self) -> Vec<f32> {
180	        vec![
181	            self.n_stops_norm as f32,
182	            self.n_vehicles_norm as f32,
183	            self.avg_pairwise_km_norm as f32,
184	            self.lat_spread_norm as f32,
185	            self.lon_spread_norm as f32,
186	            self.density_norm as f32,
187	            self.area_km2_norm as f32,
188	            self.depot_centroid_dist_norm as f32,
189	            self.knn_avg_degree as f32,
190	            self.knn_max_degree as f32,
191	            self.knn_clustering as f32,
192	            self.knn_diameter_norm as f32,
193	            self.knn_mst_weight_norm as f32,
194	            self.knn_avg_shortest_path as f32,
195	            self.knn_spectral_gap as f32,
196	            self.knn_assortativity as f32,
197	            self.total_demand_norm as f32,
198	            self.demand_std_norm as f32,
199	            self.tight_capacity_flag as f32,
200	            self.capacity_ratio as f32,
201	            self.dist_mean_norm as f32,
202	            self.dist_std_norm as f32,
203	            self.dist_skewness as f32,
204	            self.depot_dist_mean_norm as f32,
205	            self.objective_min_distance as f32,
206	            self.objective_min_time as f32,
207	            self.objective_balance_load as f32,
208	            self.objective_min_vehicles as f32,
209	        ]
210	    }
211	}
212	
213	// ── kNN graph helpers ────────────────────────────────────────────────
214	
215	#[derive(Debug, Clone, Default)]
216	struct KnnFeatures {
217	    avg_degree: f64,
218	    max_degree: f64,
219	    clustering: f64,
220	    diameter: f64,
221	    mst_weight: f64,
222	    avg_shortest_path: f64,
223	    spectral_gap: f64,
224	    assortativity: f64,
225	}
226	
227	fn knn_graph_features(stops: &[&VRPSolverStop], k: usize) -> KnnFeatures {
228	    let n = stops.len();
229	    if n < 2 {
230	        return KnnFeatures::default();
231	    }
232	    let k = k.min(n - 1).max(1);
233	
234	    // Build distance matrix
235	    let mut dists = vec![vec![0.0; n]; n];
236	    for i in 0..n {
237	        for j in (i + 1)..n {
238	            let d = haversine_m(stops[i].lat, stops[i].lon, stops[j].lat, stops[j].lon) / 1000.0;
239	            dists[i][j] = d;
240	            dists[j][i] = d;
241	        }
242	    }
243	
244	    // kNN adjacency list
245	    let mut adj: Vec<Vec<usize>> = vec![vec![]; n];
246	    let mut degrees = vec![0usize; n];
247	    for i in 0..n {
248	        let mut neighbors: Vec<(usize, f64)> = (0..n)
249	            .filter(|&j| j != i)
250	            .map(|j| (j, dists[i][j]))
251	            .collect();
252	        neighbors.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));
253	        for &(j, _) in neighbors.iter().take(k) {
254	            adj[i].push(j);
255	            adj[j].push(i);
256	            degrees[i] += 1;
257	            degrees[j] += 1;
258	        }
259	    }
260	
261	    let avg_degree = degrees.iter().sum::<usize>() as f64 / n as f64;
262	    let max_degree = *degrees.iter().max().unwrap_or(&0) as f64;
263	
264	    // Clustering coefficient (local)
265	    let mut clustering_sum = 0.0;
266	    for i in 0..n {
267	        let neighbors = &adj[i];
268	        let di = neighbors.len();
269	        if di < 2 {
270	            continue;
271	        }
272	        let mut edges_between = 0;
273	        for a in 0..di {
274	            for b in (a + 1)..di {
275	                if adj[neighbors[a]].contains(&neighbors[b]) {
276	                    edges_between += 1;
277	                }
278	            }
279	        }
280	        let possible = di * (di - 1) / 2;
281	        clustering_sum += edges_between as f64 / possible as f64;
282	    }
283	    let clustering = clustering_sum / n as f64;
284	
285	    // MST weight (Prim)
286	    let mst_weight = prim_mst(&dists);
287	
288	    // Diameter & avg shortest path (Floyd-Warshall for small n)
289	    let (diameter, avg_sp) = if n <= 200 {
290	        let (sp, diam, avg) = all_pairs_shortest_paths(&dists);
291	        (diam, avg)
292	    } else {
293	        // For large n, approximate with sampled pairs
294	        let mut max_d = 0.0;
295	        let mut sum_d = 0.0;
296	        let mut count = 0;
297	        let sample = (n * 10).min(2000);
298	        for _ in 0..sample {
299	            let i = (rand_u32() as usize) % n;
300	            let j = (rand_u32() as usize) % n;
301	            if i == j { continue; }
302	            let d = dists[i][j];
303	            if d > max_d { max_d = d; }
304	            sum_d += d;
305	            count += 1;
306	        }
307	        (max_d, if count > 0 { sum_d / count as f64 } else { 0.0 })
308	    };
309	
310	    // Spectral gap (approximate from degree sequence)
311	    let spectral_gap = max_degree - avg_degree;
312	
313	    // Assortativity (degree correlation)
314	    let mut sum_xy = 0.0;
315	    let mut sum_x = 0.0;
316	    let mut sum_y = 0.0;
317	    let mut sum_x2 = 0.0;
318	    let mut sum_y2 = 0.0;
319	    let mut edge_count = 0;
320	    for i in 0..n {
321	        for &j in &adj[i] {
322	            if i >= j { continue; }
323	            let di = degrees[i] as f64;
324	            let dj = degrees[j] as f64;
325	            sum_xy += di * dj;
326	            sum_x += di;
327	            sum_y += dj;
328	            sum_x2 += di * di;
329	            sum_y2 += dj * dj;
330	            edge_count += 1;
331	        }
332	    }
333	    let assortativity = if edge_count > 0 {
334	        let ex = sum_x / edge_count as f64;
335	        let ey = sum_y / edge_count as f64;
336	        let ex2 = sum_x2 / edge_count as f64;
337	        let ey2 = sum_y2 / edge_count as f64;
338	        let cov = (sum_xy / edge_count as f64) - ex * ey;
339	        let var_x = ex2 - ex * ex;
340	        let var_y = ey2 - ey * ey;
341	        if var_x > 0.0 && var_y > 0.0 {
342	            cov / (var_x.sqrt() * var_y.sqrt())
343	        } else {
344	            0.0
345	        }
346	    } else {
347	        0.0
348	    };
349	
350	    KnnFeatures {
351	        avg_degree,
352	        max_degree,
353	        clustering,
354	        diameter,
355	        mst_weight,
356	        avg_shortest_path: avg_sp,
357	        spectral_gap,
358	        assortativity,
359	    }
360	}
