 1	use anyhow::{Context, Result};
 2	use candle_core::{Device, Tensor};
 3	use candle_nn::VarBuilder;
 4	use candle_transformers::models::bert::{BertModel, Config, DTYPE};
 5	use hf_hub::{api::sync::Api, Repo};
 6	use tokenizers::{PaddingParams, Tokenizer};
 7	
 8	pub struct Embedder {
 9	    model: BertModel,
10	    tokenizer: Tokenizer,
11	    device: Device,
12	}
13	
14	impl Embedder {
15	    pub fn new() -> Result<Self> {
16	        let device = crate::core::ml::best_device()?;
17	        let api = Api::new()?;
18	        let repo = api.repo(Repo::model("BAAI/bge-small-en-v1.5".to_string()));
19	
20	        let config_filename = repo.get("config.json")?;
21	        let tokenizer_filename = repo.get("tokenizer.json")?;
22	        let weights_filename = repo.get("model.safetensors")?;
23	
24	        let config = std::fs::read_to_string(config_filename)?;
25	        let config: Config = serde_json::from_str(&config)?;
26	        let mut tokenizer = Tokenizer::from_file(tokenizer_filename)
27	            .map_err(anyhow::Error::msg)
28	            .context("Failed to load tokenizer")?;
29	
30	        let tensors = candle_core::safetensors::load(&weights_filename, &device)?;
31	        let vb = VarBuilder::from_tensors(tensors, DTYPE, &device);
32	        let model = BertModel::load(vb, &config)?;
33	
34	        if let Some(pp) = tokenizer.get_padding_mut() {
35	            pp.strategy = tokenizers::PaddingStrategy::BatchLongest;
36	        } else {
37	            let pp = PaddingParams {
38	                strategy: tokenizers::PaddingStrategy::BatchLongest,
39	                ..Default::default()
40	            };
41	            tokenizer.with_padding(Some(pp));
42	        }
43	
44	        Ok(Self {
45	            model,
46	            tokenizer,
47	            device,
48	        })
49	    }
50	
51	    pub fn embed(&mut self, texts: Vec<String>) -> Result<Vec<Vec<f32>>> {
52	        let tokens = self.tokenizer.encode_batch(texts, true)
53	            .map_err(anyhow::Error::msg)
54	            .context("Failed to tokenize batch")?;
55	
56	        let token_ids = tokens.iter()
57	            .map(|tokens| {
58	                let tokens = tokens.get_ids().to_vec();
59	                Ok(Tensor::new(tokens.as_slice(), &self.device)?)
60	            })
61	            .collect::<Result<Vec<_>>>()?;
62	
63	        let token_ids = Tensor::stack(&token_ids, 0)?;
64	        let token_type_ids = token_ids.zeros_like()?;
65	        
66	        let embeddings = self.model.forward(&token_ids, &token_type_ids, None)?;
67	        
68	        // Mean pooling
69	        let (_n_batch, n_tokens, _hidden_size) = embeddings.dims3()?;
70	        let embeddings = (embeddings.sum(1)? / (n_tokens as f64))?;
71	        
72	        // Normalize
73	        let norm = embeddings.sqr()?.sum_keepdim(1)?.sqrt()?;
74	        let embeddings = embeddings.broadcast_div(&norm)?;
75	        
76	        let embeddings = embeddings.to_vec2::<f32>()?;
77	        Ok(embeddings)
78	    }
79	}
80	
81	pub fn run_embed(texts: Vec<String>) -> Result<Vec<Vec<f32>>> {
82	    let mut embedder = Embedder::new()?;
83	    embedder.embed(texts)
84	}

  1	//! Natural Language Query Parser for VRP routing.
  2	//!
  3	//! Converts free-text routing requests into structured VRP JSON configs.
  4	//!
  5	//! Example:
  6	//!   "Route 50 packages with 5 vans starting at 45.5,-73.6 by 5pm"
  7	//!   → {"num_stops":50, "num_vehicles":5, "depot":[45.5,-73.6], "deadline":"17:00"}
  8	//!
  9	//! Research basis: "From Words to Routes" (2403.10795, 2024)
 10	//!
 11	//! Design: Hybrid approach
 12	//!   1. Regex-based entity extraction (numbers, coordinates, times)
 13	//!   2. Intent classification via keyword matching
 14	//!   3. Template-based JSON generation with slot filling
 15	//!   4. (Future) Small fine-tuned LLM for complex/ambiguous queries
 16	
 17	use serde::{Deserialize, Serialize};
 18	use std::collections::HashMap;
 19	
 20	#[cfg(feature = "ml")]
 21	use candle_core::{Device, Tensor, DType};
 22	#[cfg(feature = "ml")]
 23	use candle_nn::VarBuilder;
 24	#[cfg(feature = "ml")]
 25	use candle_transformers::models::qwen2::{ModelForCausalLM, Config};
 26	#[cfg(feature = "ml")]
 27	use candle_transformers::generation::LogitsProcessor;
 28	#[cfg(feature = "ml")]
 29	use hf_hub::{api::sync::Api, Repo, RepoType};
 30	#[cfg(feature = "ml")]
 31	use tokenizers::Tokenizer;
 32	#[cfg(feature = "ml")]
 33	use anyhow::{Context, Result};
 34	
 35	/// Parsed VRP configuration from natural language.
 36	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 37	pub struct ParsedRoutingQuery {
 38	    /// Variant: CVRP, CVRPTW, mTSP, CPP, etc.
 39	    pub variant: String,
 40	    /// Number of stops / packages / customers.
 41	    pub num_stops: Option<u32>,
 42	    /// Number of vehicles / vans / drivers.
 43	    pub num_vehicles: Option<u32>,
 44	    /// Depot coordinates [lat, lon].
 45	    pub depot: Option<(f64, f64)>,
 46	    /// Time window deadline (HH:MM or ISO).
 47	    pub deadline: Option<String>,
 48	    /// Vehicle capacity.
 49	    pub capacity: Option<f64>,
 50	    /// Average speed km/h.
 51	    pub avg_speed_kmh: Option<f64>,
 52	    /// Optimization objective.
 53	    pub objective: Option<String>,
 54	    /// Source data bbox (if extracting network).
 55	    pub bbox: Option<BoundingBox>,
 56	    /// Raw extracted entities for debugging.
 57	    pub entities: HashMap<String, String>,
 58	}
 59	
 60	#[derive(Debug, Clone, Serialize, Deserialize)]
 61	pub struct BoundingBox {
 62	    pub min_lon: f64,
 63	    pub min_lat: f64,
 64	    pub max_lon: f64,
 65	    pub max_lat: f64,
 66	}
 67	
 68	/// Parse a natural language routing query.
 69	pub fn parse_query(query: &str) -> ParsedRoutingQuery {
 70	    let lower = query.to_lowercase();
 71	    let mut entities = HashMap::new();
 72	    let mut result = ParsedRoutingQuery::default();
 73	
 74	    // ── Intent classification ─────────────────────────────────────────
 75	    if lower.contains("sweep") || lower.contains("street") || lower.contains("road") {
 76	        result.variant = "cpp".to_string();
 77	    } else if lower.contains("time window") || lower.contains("by ") || lower.contains("deadline") {
 78	        result.variant = "cvrptw".to_string();
 79	    } else if lower.contains("package") || lower.contains("delivery") || lower.contains("customer") {
 80	        result.variant = "cvrp".to_string();
 81	    } else if lower.contains("multiple depot") || lower.contains("multi-depot") {
 82	        result.variant = "mdvrp".to_string();
 83	    } else {
 84	        result.variant = "cvrp".to_string();
 85	    }
 86	
 87	    // ── Entity extraction: numbers ──────────────────────────────────
 88	    // "50 packages", "5 vans", "100 customers", etc.
 89	    let num_regex = regex::Regex::new(r"(\d+)\s*(package|stop|customer|van|vehicle|driver|truck|route)").unwrap();
 90	    for cap in num_regex.captures_iter(&lower) {
 91	        let num: u32 = cap[1].parse().unwrap_or(0);
 92	        let noun = &cap[2];
 93	        entities.insert(noun.to_string(), num.to_string());
 94	        match noun {
 95	            "package" | "stop" | "customer" => result.num_stops = Some(num),
 96	            "van" | "vehicle" | "driver" | "truck" | "route" => result.num_vehicles = Some(num),
 97	            _ => {}
 98	        }
 99	    }
100	
101	    // ── Entity extraction: coordinates ────────────────────────────────
102	    // "45.5, -73.6" or "lat 45.5 lon -73.6"
103	    let coord_regex = regex::Regex::new(
104	        r"(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)"
105	    ).unwrap();
106	    if let Some(cap) = coord_regex.captures(&lower) {
107	        let lat: f64 = cap[1].parse().unwrap_or(0.0);
108	        let lon: f64 = cap[2].parse().unwrap_or(0.0);
109	        if lat.abs() <= 90.0 && lon.abs() <= 180.0 {
110	            result.depot = Some((lat, lon));
111	            entities.insert("depot".to_string(), format!("{}, {}", lat, lon));
112	        }
113	    }
114	
115	    // ── Entity extraction: time ─────────────────────────────────────
116	    // "by 5pm", "before 17:00", "deadline 5:30 PM"
117	    let time_regex = regex::Regex::new(
118	        r"(?:by|before|deadline|until)\s*(\d{1,2}):?(\d{2})?\s*(am|pm)?"
119	    ).unwrap();
120	    if let Some(cap) = time_regex.captures(&lower) {
121	        let hour: u32 = cap[1].parse().unwrap_or(0);
122	        let minute: u32 = cap.get(2).and_then(|m| m.as_str().parse().ok()).unwrap_or(0);
123	        let ampm = cap.get(3).map(|m| m.as_str()).unwrap_or("");
124	        let mut h = hour;
125	        if ampm == "pm" && h < 12 { h += 12; }
126	        if ampm == "am" && h == 12 { h = 0; }
127	        let time_str = format!("{:02}:{:02}", h, minute);
128	        result.deadline = Some(time_str.clone());
129	        entities.insert("deadline".to_string(), time_str);
130	    }
131	
132	    // ── Entity extraction: capacity ─────────────────────────────────
133	    // "capacity 100", "up to 50 kg"
134	    let cap_regex = regex::Regex::new(r"capacity\s*(\d+)").unwrap();
135	    if let Some(cap) = cap_regex.captures(&lower) {
136	        let c: f64 = cap[1].parse().unwrap_or(0.0);
137	        result.capacity = Some(c);
138	        entities.insert("capacity".to_string(), c.to_string());
139	    }
140	
141	    // ── Entity extraction: speed ────────────────────────────────────
142	    let speed_regex = regex::Regex::new(r"(\d+)\s*km/h").unwrap();
143	    if let Some(cap) = speed_regex.captures(&lower) {
144	        let s: f64 = cap[1].parse().unwrap_or(0.0);
145	        result.avg_speed_kmh = Some(s);
146	        entities.insert("speed".to_string(), s.to_string());
147	    }
148	
149	    // ── Objective extraction ────────────────────────────────────────
150	    if lower.contains("shortest") || lower.contains("min distance") || lower.contains("fastest route") {
151	        result.objective = Some("min_distance".to_string());
152	    } else if lower.contains("min time") || lower.contains("quickest") {
153	        result.objective = Some("min_time".to_string());
154	    } else if lower.contains("balance") || lower.contains("even") || lower.contains("fair") {
155	        result.objective = Some("balance_load".to_string());
156	    } else if lower.contains("min vehicle") || lower.contains("fewest") {
157	        result.objective = Some("min_vehicles".to_string());
158	    }
159	
160	    // ── Bounding box extraction (loose) ─────────────────────────────
161	    // "area around 45.5,-73.6" or "in Montreal"
162	    if let Some((lat, lon)) = result.depot {
163	        let delta = 0.05; // ~5km
164	        result.bbox = Some(BoundingBox {
165	            min_lat: lat - delta,
166	            max_lat: lat + delta,
167	            min_lon: lon - delta,
168	            max_lon: lon + delta,
169	        });
170	    }
171	
172	    result.entities = entities;
173	    result
174	}
175	
176	/// Convert a parsed query to a VRP solver JSON payload.
177	pub fn to_vrp_json(parsed: &ParsedRoutingQuery) -> serde_json::Value {
178	    let mut obj = serde_json::json!({
179	        "variant": parsed.variant,
180	    });
181	
182	    if let Some(n) = parsed.num_stops {
183	        obj["num_stops"] = serde_json::json!(n);
184	    }
185	    if let Some(v) = parsed.num_vehicles {
186	        obj["num_vehicles"] = serde_json::json!(v);
187	    }
188	    if let Some((lat, lon)) = parsed.depot {
189	        obj["depot"] = serde_json::json!({"lat": lat, "lon": lon});
190	    }
191	    if let Some(ref d) = parsed.deadline {
192	        obj["deadline"] = serde_json::json!(d);
193	    }
194	    if let Some(c) = parsed.capacity {
195	        obj["capacity"] = serde_json::json!(c);
196	    }
197	    if let Some(s) = parsed.avg_speed_kmh {
198	        obj["avg_speed_kmh"] = serde_json::json!(s);
199	    }
200	    if let Some(ref o) = parsed.objective {
201	        obj["objective"] = serde_json::json!(o);
202	    }
203	    if let Some(ref b) = parsed.bbox {
204	        obj["bbox"] = serde_json::json!({
205	            "min_lon": b.min_lon,
206	            "min_lat": b.min_lat,
207	            "max_lon": b.max_lon,
208	            "max_lat": b.max_lat,
209	        });
210	    }
211	
212	    obj
213	}
