  51	#[derive(Debug, Deserialize)]
  52	struct Request {
  53	    jsonrpc: String,
  54	    method: String,
  55	    #[serde(default)]
  56	    params: Value,
  57	    #[serde(default)]
  58	    id: Value,
  59	}
