 905	fn parse_bbox(args: &Value) -> anyhow::Result<BBoxRequest> {
 906	    let bbox = args
 907	        .get("bbox")
 908	        .ok_or_else(|| anyhow::anyhow!("Missing 'bbox' parameter"))?;
 909	    Ok(BBoxRequest {
 910	        min_lon: bbox
 911	            .get("min_lon")
 912	            .and_then(|v| v.as_f64())
 913	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lon required"))?,
 914	        min_lat: bbox
 915	            .get("min_lat")
 916	            .and_then(|v| v.as_f64())
 917	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lat required"))?,
 918	        max_lon: bbox
 919	            .get("max_lon")
 920	            .and_then(|v| v.as_f64())
 921	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lon required"))?,
 922	        max_lat: bbox
 923	            .get("max_lat")
 924	            .and_then(|v| v.as_f64())
 925	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lat required"))?,
 926	    })
 927	}
 928	
 929	fn parse_road_classes(args: &Value) -> Vec<RoadClass> {
 930	    let Some(arr) = args.get("road_classes").and_then(|v| v.as_array()) else {
 931	        return RoadClass::all_vehicle();
 932	    };
 933	    if arr.is_empty() {
 934	        return RoadClass::all_vehicle();
 935	    }
 936	    arr.iter()
 937	        .filter_map(|v| v.as_str())
 938	        .filter_map(|s| match s {
