1208	async fn handle_vrp_solve(args: &Value) -> Result<Value> {
1209	    let stops_val = args
1210	        .get("stops")
1211	        .and_then(|v| v.as_array())
1212	        .ok_or_else(|| anyhow::anyhow!("Missing 'stops' parameter"))?;
1213	
1214	    if stops_val.is_empty() {
1215	        anyhow::bail!("At least one stop (the depot) is required");
1216	    }
1217	
1218	    let stops: Vec<VRPSolverStop> = stops_val
1219	        .iter()
1220	        .enumerate()
1221	        .map(|(i, s)| {
1222	            let lat = s.get("lat").and_then(|v| v.as_f64())
1223	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lat'", i))?;
1224	            let lon = s.get("lon").and_then(|v| v.as_f64())
1225	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lon'", i))?;
1226	            let label = s.get("label").and_then(|v| v.as_str())
1227	                .unwrap_or_else(|| "")
1228	                .to_string();
1229	            let demand = s.get("demand").and_then(|v| v.as_f64());
1230	            Ok(VRPSolverStop {
1231	                lat,
1232	                lon,
1233	                label: if label.is_empty() { format!("Stop {}", i) } else { label },
1234	                demand,
1235	                arrival_time: None,
1236	            })
1237	        })
1238	        .collect::<Result<Vec<_>>>()?;
1239	
1240	    let num_vehicles = args.get("num_vehicles").and_then(|v| v.as_u64()).unwrap_or(1) as usize;
1241	    let vehicle_capacity = args.get("vehicle_capacity").and_then(|v| v.as_f64()).unwrap_or(100.0);
1242	    let solver_id = args.get("solver_id").and_then(|v| v.as_str()).unwrap_or("default").to_string();
1243	    let avg_speed_kmh = args.get("avg_speed_kmh").and_then(|v| v.as_f64()).unwrap_or(40.0);
1244	    let objective = match args.get("objective").and_then(|v| v.as_str()).unwrap_or("min_distance") {
1245	        "min_time" => VrpObjective::MinTime,
1246	        "balance_load" => VrpObjective::BalanceLoad,
1247	        "min_vehicles" => VrpObjective::MinVehicles,
1248	        _ => VrpObjective::MinDistance,
1249	    };
1250	
1251	    // Build haversine distance matrix
1252	    let matrix = build_haversine_matrix(&stops, avg_speed_kmh);
1253	
1254	    let input = VRPSolverInput {
1255	        locations: stops,
1256	        num_vehicles,
1257	        vehicle_capacity,
1258	        objective,
1259	        matrix: Some(matrix),
1260	        service_time_secs: None,
1261	        use_time_windows: false,
1262	        window_open: None,
1263	        window_close: None,
1264	    };
1265	
1266	    tracing::info!("vrp_solve: {} stops, {} vehicles, solver={}", 
1267	        input.locations.len(), num_vehicles, solver_id);
1268	
1269	    let output = solve_with(&solver_id, &input).await
1270	        .map_err(|e| anyhow::anyhow!("VRP solver failed: {}", e))?;
1271	
1272	    // Convert routes to JSON
1273	    let routes_json: Vec<Value> = output.routes.iter().flatten().enumerate().map(|(vi, route)| {
1274	        let stops_json: Vec<Value> = route.iter().map(|s| {
1275	            json!({
1276	                "lat": s.lat,
1277	                "lon": s.lon,
1278	                "label": s.label,
1279	                "demand": s.demand,
1280	            })
1281	        }).collect();
1282	        json!({
1283	            "vehicle": vi,
1284	            "stops": stops_json,
1285	        })
1286	    }).collect();
1287	
1288	    Ok(json!({
1289	        "total_distance_km": output.total_distance_km,
1290	        "total_time_min": output.total_time_min,
1291	        "routes": routes_json,
1292	        "unassigned": output.unassigned,
1293	    }))
1294	}
