1416	fn handle_haversine_distance(args: &Value) -> Result<Value> {
1417	    let from = args
1418	        .get("from")
1419	        .ok_or_else(|| anyhow::anyhow!("Missing 'from' parameter"))?;
1420	    let to = args
1421	        .get("to")
1422	        .ok_or_else(|| anyhow::anyhow!("Missing 'to' parameter"))?;
1423	
1424	    let lat1 = from.get("lat").and_then(|v| v.as_f64())
1425	        .ok_or_else(|| anyhow::anyhow!("from.lat required"))?;
1426	    let lon1 = from.get("lon").and_then(|v| v.as_f64())
