1511	
1512	fn handle_fuel_estimate(args: &Value) -> Result<Value> {
1513	    let samples_val = args
1514	        .get("samples")
1515	        .and_then(|v| v.as_array())
1516	        .ok_or_else(|| anyhow::anyhow!("Missing 'samples' parameter"))?;
1517	
1518	    if samples_val.len() < 2 {
1519	        anyhow::bail!("At least 2 samples are required for fuel estimation");
1520	    }
1521	
1522	    let base_consumption = args
1523	        .get("base_consumption")
1524	        .and_then(|v| v.as_f64())
1525	        .unwrap_or(0.08);
1526	
1527	    // Build an ElevationProfile from the samples
1528	    let points: Vec<v2rmp::core::elevation::RouteElevationPoint> = samples_val
1529	        .iter()
1530	        .enumerate()
1531	        .map(|(i, s)| {
1532	            let distance_m = s.get("distance_m").and_then(|v| v.as_f64())
1533	                .ok_or_else(|| anyhow::anyhow!("Sample {} missing 'distance_m'", i))?;
1534	            let elevation_m = s.get("elevation_m").and_then(|v| v.as_f64())
1535	                .ok_or_else(|| anyhow::anyhow!("Sample {} missing 'elevation_m'", i))?;
1536	            Ok(v2rmp::core::elevation::RouteElevationPoint {
1537	                distance_m,
1538	                elevation_m: Some(elevation_m),
1539	                point: v2rmp::core::elevation::Point { lon: 0.0, lat: 0.0 },
1540	            })
1541	        })
1542	        .collect::<Result<Vec<_>>>()?;
1543	
1544	    let total_distance_km = points.last().map(|p| p.distance_m / 1000.0).unwrap_or(0.0);
1545	
1546	    let profile = v2rmp::core::elevation::ElevationProfile {
1547	        points,
1548	        total_ascent: 0.0, // Not needed for fuel calc
1549	        total_descent: 0.0,
1550	        max_elevation: 0.0,
1551	        min_elevation: 0.0,
1552	        avg_elevation: 0.0,
1553	        distance_km: total_distance_km,
1554	    };
1555	
1556	    let consumption = FuelCalculator::calculate(&profile, base_consumption);
1557	
1558	    Ok(json!({
1559	        "total_fuel_l": consumption.total_fuel_l,
1560	        "avg_consumption_l_per_km": consumption.avg_consumption_l_per_km,
1561	        "elevation_penalty_l": consumption.elevation_penalty_l,
1562	        "elevation_benefit_l": consumption.elevation_benefit_l,
1563	        "base_consumption_l_per_km": base_consumption,
1564	        "distance_km": total_distance_km,
1565	    }))
1566	}
