1834	// ── Pipeline handler ─────────────────────────────────────────────────────
1835	
1836	async fn handle_pipeline(args: &Value) -> Result<Value> {
1837	    let bbox = parse_bbox(args)?;
1838	    let output_dir = args
1839	        .get("output_dir")
1840	        .and_then(|v| v.as_str())
1841	        .unwrap_or("./pipeline-output")
1842	        .to_string();
1843	    let source = match args.get("source").and_then(|v| v.as_str()).unwrap_or("overture") {
1844	        "osm" => ExtractSource::Osm,
1845	        _ => ExtractSource::Overture,
1846	    };
1847	    let pbf_path = args.get("pbf_path").and_then(|v| v.as_str()).map(String::from);
1848	    let depot = args.get("depot").and_then(|d| {
1849	        let lat = d.get("lat")?.as_f64()?;
1850	        let lon = d.get("lon")?.as_f64()?;
1851	        Some((lat, lon))
1852	    });
1853	    let mode = parse_solver_mode(args);
1854	    let prune_disconnected = args.get("prune_disconnected").and_then(|v| v.as_bool()).unwrap_or(false);
1855	
1856	    // Ensure output directory exists
1857	    std::fs::create_dir_all(&output_dir)?;
1858	
1859	    let extract_path = format!("{}/extract.geojson", output_dir);
1860	    let cleaned_path = format!("{}/cleaned.geojson", output_dir);
1861	    let rmp_path = format!("{}/network.rmp", output_dir);
1862	    let route_path = format!("{}/route.gpx", output_dir);
1863	
1864	    // Stage 1: Extract
1865	    tracing::info!("pipeline stage 1: extract");
1866	    let extract_req = ExtractRequest {
1867	        source,
1868	        bbox,
1869	        road_classes: RoadClass::all_vehicle(),
1870	        output_path: extract_path.clone(),
1871	        pbf_path,
1872	    };
1873	    let extract_result = v2rmp::core::extract::run_extract(&extract_req).await?;
1874	
1875	    // Stage 2: Clean
1876	    tracing::info!("pipeline stage 2: clean");
1877	    let input_data = std::fs::read_to_string(&extract_path)?;
1878	    let geojson: geojson::FeatureCollection = serde_json::from_str(&input_data)?;
1879	    let (cleaned, clean_stats, _warnings) = clean_geojson(&geojson, &CleanOptions::default())?;
1880	    let cleaned_str = serde_json::to_string_pretty(&cleaned)?;
1881	    std::fs::write(&cleaned_path, &cleaned_str)?;
1882	
1883	    // Stage 3: Compile
1884	    tracing::info!("pipeline stage 3: compile");
1885	    let compile_req = CompileRequest {
1886	        input_geojson: cleaned_path.clone(),
1887	        output_rmp: rmp_path.clone(),
1888	        compress: false,
1889	        road_classes: vec![],
1890	        clean_options: None,
1891	        prune_disconnected,
1892	    };
1893	    let compile_result = v2rmp::core::compile::run_compile(&compile_req)?;
1894	
1895	    // Stage 4: Optimize
1896	    tracing::info!("pipeline stage 4: optimize");
1897	    let num_vehicles = args.get("num_vehicles").and_then(|v| v.as_u64()).unwrap_or(1) as usize;
1898	    let solver_id = args.get("solver_id").and_then(|v| v.as_str()).unwrap_or("clarke_wright").to_string();
1899	let optimize_req = OptimizeRequest {
1900	    cache_file: rmp_path.clone(),
1901	    route_file: Some(route_path.clone()),
1902	    turn_penalties: TurnPenalties::default(),
1903	    depot,
1904	    oneway_mode: OnewayMode::default(),
1905	    mode,
1906	    num_vehicles,
1907	    solver_id,
1908	    coordinates: None,
1909	};
1910	    let optimize_result = v2rmp::core::optimize::run_optimize(&optimize_req).await?;
1911	
1912	    Ok(json!({
1913	        "output_dir": output_dir,
1914	        "extract": {
