 21	//! Dynamic solver registry: built-ins first, then dynamically registered solvers.
 22	
 23	use super::solvers::clarke_wright::ClarkeWrightSolver;
 24	use super::solvers::default::DefaultSolver;
 25	use super::solvers::or_opt::OrOptSolver;
 26	use super::solvers::sweep::SweepSolver;
 27	use super::solvers::two_opt::TwoOptSolver;
 28	use super::types::{VRPSolver, VRPSolverInput, VRPSolverOutput};
 29	use std::collections::HashMap;
 30	use std::sync::{Arc, OnceLock, RwLock};
 31	
 32	static REGISTRY: OnceLock<RwLock<SolverRegistryInner>> = OnceLock::new();
 33	
 34	fn registry() -> &'static RwLock<SolverRegistryInner> {
 35	    REGISTRY.get_or_init(|| RwLock::new(SolverRegistryInner::new()))
 36	}
 37	
 38	struct SolverRegistryInner {
 39	    solvers: HashMap<String, Arc<dyn VRPSolver>>,
 40	    builtin_ids: Vec<String>,
 41	    dynamic_order: Vec<String>,
 42	}
 43	
 44	impl SolverRegistryInner {
 45	    fn new() -> Self {
 46	        let builtins: Vec<Arc<dyn VRPSolver>> = vec![
 47	            Arc::new(ClarkeWrightSolver),
 48	            Arc::new(SweepSolver),
 49	            Arc::new(OrOptSolver),
 50	            Arc::new(TwoOptSolver),
 51	            Arc::new(DefaultSolver),
 52	        ];
 53	        let builtin_ids: Vec<String> = builtins.iter().map(|s| s.id().to_string()).collect();
 54	        let mut solvers = HashMap::new();
 55	        for s in builtins {
 56	            let id = s.id().to_string();
 57	            solvers.insert(id, s);
 58	        }
 59	        Self {
 60	            solvers,
 61	            builtin_ids,
 62	            dynamic_order: Vec::new(),
 63	        }
 64	    }
 65	}
 66	
 67	/// Register a custom solver. If the id already exists, it is replaced.
 68	pub fn register_solver(solver: Arc<dyn VRPSolver>) {
 69	    let id = solver.id().to_string();
 70	    let mut reg = registry().write().unwrap();
 71	    let had = reg.solvers.contains_key(&id);
 72	    reg.solvers.insert(id.clone(), solver);
 73	    if !had && !reg.builtin_ids.contains(&id) {
 74	        reg.dynamic_order.push(id);
 75	    }
 76	}
 77	
 78	/// Unregister a solver by id. Built-in solver ids are ignored.
 79	/// Returns true if a dynamic solver was removed.
 80	pub fn unregister_solver(id: &str) -> bool {
 81	    let mut reg = registry().write().unwrap();
 82	    if reg.builtin_ids.contains(&id.to_string()) {
 83	        return false;
 84	    }
 85	    let removed = reg.solvers.remove(id).is_some();
 86	    if removed {
 87	        reg.dynamic_order.retain(|x| x != id);
 88	    }
 89	    removed
 90	}
 91	
 92	/// Return the ordered list of solvers: built-ins first, then dynamically registered.
 93	pub fn get_solver_list() -> Vec<String> {
 94	    let reg = registry().read().unwrap();
 95	    let mut ids: Vec<String> = reg.builtin_ids.clone();
 96	    for id in &reg.dynamic_order {
 97	        if reg.solvers.contains_key(id) {
 98	            ids.push(id.clone());
 99	        }
100	    }
101	    ids
102	}
103	
104	/// Solve using a solver by id. Falls back to default.
105	pub async fn solve_with(id: &str, input: &VRPSolverInput) -> Result<VRPSolverOutput, String> {
106	    // Clone the Arc out before .await so we don't hold RwLockReadGuard across await.
107	    let solver: Arc<dyn VRPSolver> = {
108	        let reg = registry().read().unwrap();
109	        match reg.solvers.get(id).or_else(|| reg.solvers.get("default")) {
110	            Some(s) => Arc::clone(s),
111	            None => return Err(format!("Solver '{id}' not found and no default available")),
112	        }
113	    };
114	    solver.solve(input).await
115	}
116	
117	/// Algorithm options for UI dropdowns.
118	pub fn get_algorithm_options() -> Vec<(String, String)> {
119	    let ids = get_solver_list();
120	    let reg = registry().read().unwrap();
121	    ids.iter()
122	        .filter_map(|id| {
123	            reg.solvers
124	                .get(id)
125	                .map(|s| (s.id().to_string(), s.label().to_string()))
126	        })
127	        .collect()
128	}
