 21	//! Geometric and routing utilities for VRP solvers.
 22	//!
 23	//! Provides distance-matrix construction, zone clustering,
 24	//! nearest-neighbor routing, 2-opt improvement, and Valhalla matrix fetching.
 25	
 26	use super::super::haversine_m;
 27	use super::types::{DistCell, DistMatrix, VRPSolverStop};
 28	
 29	/// Haversine distance between two WGS-84 coordinates, in km.
 30	pub fn haversine_km(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
 31	    haversine_m(lat1, lon1, lat2, lon2) / 1000.0
 32	}
 33	
 34	/// Build a full O(n²) distance/time matrix using haversine.
 35	/// Time estimated at `avg_speed_kmh` (default 40 km/h).
 36	pub fn build_haversine_matrix(locations: &[VRPSolverStop], avg_speed_kmh: f64) -> DistMatrix {
 37	    let n = locations.len();
 38	    let mut matrix = Vec::with_capacity(n);
 39	    for (i, _) in locations.iter().enumerate().take(n) {
 40	        let mut row = Vec::with_capacity(n);
 41	        for j in 0..n {
 42	            let dist = haversine_km(
 43	                locations[i].lat,
 44	                locations[i].lon,
 45	                locations[j].lat,
 46	                locations[j].lon,
 47	            );
 48	            let time_sec = (dist / avg_speed_kmh) * 3600.0;
 49	            row.push(DistCell {
 50	                distance: dist,
 51	                time: time_sec,
 52	            });
 53	        }
 54	        matrix.push(row);
 55	    }
 56	    matrix
 57	}
 58	
 59	/// Fetch a real-road distance/time matrix from Valhalla.
 60	pub async fn get_valhalla_matrix(locations: &[VRPSolverStop]) -> Result<DistMatrix, String> {
 61	    let url = "https://valhalla1.openstreetmap.de/sources_to_targets";
 62	    let locs: Vec<serde_json::Value> = locations
 63	        .iter()
 64	        .map(|l| serde_json::json!({"lat": l.lat, "lon": l.lon}))
 65	        .collect();
 66	
 67	    let body = serde_json::json!({
 68	        "sources": locs,
 69	        "targets": locs,
 70	        "costing": "auto",
 71	        "directions_options": { "units": "kilometers" }
 72	    });
 73	
 74	    let client = reqwest::Client::new();
 75	    let resp = client
 76	        .post(url)
 77	        .json(&body)
 78	        .send()
 79	        .await
 80	        .map_err(|e| format!("Valhalla request failed: {e}"))?;
 81	
 82	    if !resp.status().is_success() {
 83	        return Err(format!("Valhalla HTTP {}", resp.status()));
 84	    }
 85	
 86	    let data: serde_json::Value = resp
 87	        .json()
 88	        .await
 89	        .map_err(|e| format!("Valhalla parse error: {e}"))?;
 90	
 91	    let stt = data
 92	        .get("sources_to_targets")
 93	        .ok_or("Invalid Valhalla response: missing sources_to_targets")?;
 94	
 95	    let rows = stt
 96	        .as_array()
 97	        .ok_or("Invalid Valhalla response: sources_to_targets not an array")?;
 98	    let n = rows.len();
 99	    let mut matrix = Vec::with_capacity(n);
100	    for row_val in rows {
101	        let row = row_val.as_array().ok_or("Invalid Valhalla row")?;
102	        let mut matrix_row = Vec::with_capacity(n);
103	        for cell_val in row {
104	            let cell = cell_val.as_object();
105	            let (dist, time) = match cell {
106	                Some(c) => (
107	                    c.get("distance").and_then(|v| v.as_f64()).unwrap_or(0.0),
108	                    c.get("time").and_then(|v| v.as_f64()).unwrap_or(0.0),
109	                ),
110	                None => (0.0, 0.0),
111	            };
112	            matrix_row.push(DistCell {
113	                distance: dist,
114	                time,
115	            });
116	        }
117	        matrix.push(matrix_row);
118	    }
119	    Ok(matrix)
120	}
