237	/// 2-opt improvement: iteratively reverse segments to reduce total distance.
238	pub fn two_opt_improve(matrix: &DistMatrix, route_indices: &[usize]) -> Vec<usize> {
239	    let n = route_indices.len();
240	    if n <= 3 {
241	        return route_indices.to_vec();
242	    }
243	    let mut route = route_indices.to_vec();
244	    let mut improved = true;
245	    let mut iterations = 0;
246	    let max_iter = 300;
247	    while improved && iterations < max_iter {
248	        improved = false;
249	        iterations += 1;
250	        for i in 0..n - 2 {
251	            for j in (i + 2)..n {
252	                let a = route[i];
253	                let b = route[i + 1];
254	                let c = route[j];
255	                let d = route[(j + 1) % n];
256	                let before = matrix_get_dist(matrix, a, b) + matrix_get_dist(matrix, c, d);
257	                let after = matrix_get_dist(matrix, a, c) + matrix_get_dist(matrix, b, d);
258	                if after < before - 1e-6 {
259	                    route[i + 1..=j].reverse();
260	                    improved = true;
261	                    break;
262	                }
263	            }
264	            if improved {
265	                break;
266	            }
267	        }
268	    }
269	    route
270	}
