272	/// Helper: get distance from matrix with fallback.
273	pub fn matrix_get_dist(matrix: &DistMatrix, i: usize, j: usize) -> f64 {
274	    matrix
275	        .get(i)
276	        .and_then(|row| row.get(j))
277	        .map(|c| c.distance)
278	        .unwrap_or(0.0)
279	}
