344	/// Parse a CSV file of coordinates into VRP solver stops.
345	///
346	/// Supported column sets:
347	///   Minimal:  lat,lon
348	///   Extended: lat,lon,label,demand,type
349	///
350	/// The `type` column accepts "depot" or "stop" (default: "stop").
351	/// If no depot is present, the first row becomes the depot.
352	/// The `demand` column is optional; defaults to 1.0 for stops, 0.0 for depots.
353	pub fn parse_csv_stops(csv_path: &str) -> Result<(Vec<crate::core::vrp::types::VRPSolverStop>, Vec<usize>), String> {
354	    use std::io::Read;
355	    let mut file = std::fs::File::open(csv_path)
356	        .map_err(|e| format!("Cannot open CSV '{}': {}", csv_path, e))?;
357	    let mut content = String::new();
358	    file.read_to_string(&mut content)
359	        .map_err(|e| format!("Cannot read CSV '{}': {}", csv_path, e))?;
360	
361	    let mut reader = csv::ReaderBuilder::new()
362	        .has_headers(true)
363	        .trim(csv::Trim::All)
364	        .from_reader(content.as_bytes());
365	
366	    let headers = reader.headers()
367	        .map_err(|e| format!("Failed to read CSV headers: {}", e))?
368	        .clone();
369	
370	    let lat_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("lat") || h.eq_ignore_ascii_case("latitude"))
371	        .ok_or("CSV must have a 'lat' column")?;
372	    let lon_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("lon") || h.eq_ignore_ascii_case("lng") || h.eq_ignore_ascii_case("longitude"))
373	        .ok_or("CSV must have a 'lon' column")?;
374	    let label_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("label") || h.eq_ignore_ascii_case("name") || h.eq_ignore_ascii_case("id"));
375	    let demand_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("demand"));
376	    let type_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("type") || h.eq_ignore_ascii_case("role"));
377	
378	    let mut stops = Vec::new();
379	    let mut depot_indices = Vec::new();
380	
381	    for (row_num, result) in reader.records().enumerate() {
382	        let record = result.map_err(|e| format!("CSV parse error at row {}: {}", row_num + 2, e))?;
383	
384	        let lat: f64 = record.get(lat_idx)
385	            .ok_or_else(|| format!("Missing lat at row {}", row_num + 2))?
386	            .parse()
387	            .map_err(|e| format!("Invalid lat at row {}: {}", row_num + 2, e))?;
388	        let lon: f64 = record.get(lon_idx)
389	            .ok_or_else(|| format!("Missing lon at row {}", row_num + 2))?
390	            .parse()
391	            .map_err(|e| format!("Invalid lon at row {}: {}", row_num + 2, e))?;
392	
393	        let label = label_idx
394	            .and_then(|i| record.get(i))
395	            .map(|s| s.to_string())
396	            .unwrap_or_else(|| format!("stop_{}", row_num));
397	
398	        let is_depot = type_idx
399	            .and_then(|i| record.get(i))
400	            .map(|s| s.eq_ignore_ascii_case("depot"))
401	            .unwrap_or(false);
402	
403	        let demand = demand_idx
404	            .and_then(|i| record.get(i))
405	            .and_then(|s| s.parse::<f64>().ok())
406	            .unwrap_or(if is_depot { 0.0 } else { 1.0 });
407	
408	        if is_depot {
409	            depot_indices.push(stops.len());
410	        }
411	
412	        stops.push(crate::core::vrp::types::VRPSolverStop {
413	            lat,
414	            lon,
415	            label,
416	            demand: Some(demand),
417	            arrival_time: None,
418	        });
419	    }
420	
421	    if stops.is_empty() {
422	        return Err("CSV file contains no data rows".to_string());
423	    }
424	
425	    // If no depot was found, designate the first stop as depot
426	    if depot_indices.is_empty() {
427	        depot_indices.push(0);
428	        if let Some(d) = stops[0].demand.as_mut() {
429	            *d = 0.0;
430	        }
431	    }
432	
433	    Ok((stops, depot_indices))
434	}
