433	// ── Statistical helpers ────────────────────────────────────────────────
434	
435	fn std_dev(vals: &[f64]) -> f64 {
436	    if vals.len() < 2 {
437	        return 0.0;
438	    }
439	    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
440	    let var = vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / (vals.len() - 1) as f64;
441	    var.sqrt()
442	}
443	
444	fn skewness(vals: &[f64]) -> f64 {
445	    if vals.len() < 3 {
446	        return 0.0;
447	    }
448	    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
449	    let std = std_dev(vals);
450	    if std == 0.0 {
451	        return 0.0;
452	    }
453	    let n = vals.len() as f64;
454	    let m3 = vals.iter().map(|v| (v - mean).powi(3)).sum::<f64>() / n;
455	    m3 / std.powi(3)
456	}
