  69	
  70	fn send(id: &Value, result: Value) {
  71	    let out = json!({
  72	        "jsonrpc": "2.0",
  73	        "id": id,
  74	        "result": result
  75	    });
  76	    let mut stdout = std::io::stdout().lock();
  77	    let _ = writeln!(stdout, "{out}");
  78	    let _ = stdout.flush();
  79	}
  80	
  81	fn send_err(id: &Value, code: i64, msg: &str) {
  82	    let out = json!({
  83	        "jsonrpc": "2.0",
  84	        "id": id,
  85	        "error": { "code": code, "message": msg }
  86	    });
  87	    let mut stdout = std::io::stdout().lock();
  88	    let _ = writeln!(stdout, "{out}");
  89	    let _ = stdout.flush();
  90	}
  91	
  92	fn tool_success(id: &Value, result: &Result<Value>) {
  93	    match result {
  94	        Ok(val) => send(
  95	            id,
  96	            json!({
  97	                "content": [{
  98	                    "type": "text",
  99	                    "text": serde_json::to_string_pretty(val).unwrap_or_default()
 100	                }]
 101	            }),
 102	        ),
 103	        Err(e) => send(
 104	            id,
 105	            json!({
 106	                "content": [{
 107	                    "type": "text",
 108	                    "text": format!("Error: {e:#}")
 109	                }],
 110	                "isError": true
 111	            }),
 112	        ),
 113	    }
 114	}
