 929	fn parse_road_classes(args: &Value) -> Vec<RoadClass> {
 930	    let Some(arr) = args.get("road_classes").and_then(|v| v.as_array()) else {
 931	        return RoadClass::all_vehicle();
 932	    };
 933	    if arr.is_empty() {
 934	        return RoadClass::all_vehicle();
 935	    }
 936	    arr.iter()
 937	        .filter_map(|v| v.as_str())
 938	        .filter_map(|s| match s {
 939	            "residential" => Some(RoadClass::Residential),
 940	            "tertiary" => Some(RoadClass::Tertiary),
 941	            "secondary" => Some(RoadClass::Secondary),
 942	            "primary" => Some(RoadClass::Primary),
 943	            "trunk" => Some(RoadClass::Trunk),
 944	            "motorway" => Some(RoadClass::Motorway),
 945	            "unclassified" => Some(RoadClass::Unclassified),
 946	            "living_street" => Some(RoadClass::LivingStreet),
 947	            "service" => Some(RoadClass::Service),
 948	            "secondary_link" => Some(RoadClass::SecondaryLink),
 949	            "primary_link" => Some(RoadClass::PrimaryLink),
 950	            "trunk_link" => Some(RoadClass::TrunkLink),
 951	            "motorway_link" => Some(RoadClass::MotorwayLink),
 952	            _ => None,
 953	        })
 954	        .collect()
 955	}
