1133	fn handle_clean(args: &Value) -> Result<Value> {
1134	    let input = args
1135	        .get("input")
1136	        .and_then(|v| v.as_str())
1137	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?
1138	        .to_string();
1139	    let output = args
1140	        .get("output")
1141	        .and_then(|v| v.as_str())
1142	        .ok_or_else(|| anyhow::anyhow!("Missing 'output' parameter"))?
1143	        .to_string();
1144	
1145	    // Build CleanOptions from args, using defaults where not specified
1146	    let defaults = CleanOptions::default();
1147	    let options = CleanOptions {
1148	        make_valid: args.get("make_valid").and_then(|v| v.as_bool()).unwrap_or(defaults.make_valid),
1149	        drop_invalid: args.get("drop_invalid").and_then(|v| v.as_bool()).unwrap_or(defaults.drop_invalid),
1150	        remove_selfloops: args.get("remove_selfloops").and_then(|v| v.as_bool()).unwrap_or(defaults.remove_selfloops),
1151	        min_length_m: args.get("min_length_m").and_then(|v| v.as_f64()).unwrap_or(defaults.min_length_m),
1152	        node_snap_m: args.get("node_snap_m").and_then(|v| v.as_f64()).unwrap_or(defaults.node_snap_m),
1153	        node_precision_decimals: args.get("node_precision_decimals").and_then(|v| v.as_u64()).map(|v| v as u32).unwrap_or(defaults.node_precision_decimals),
1154	        merge_node_positions: args.get("merge_node_positions").and_then(|v| v.as_bool()).unwrap_or(defaults.merge_node_positions),
1155	        dedupe_edges: args.get("dedupe_edges").and_then(|v| v.as_bool()).unwrap_or(defaults.dedupe_edges),
1156	        remove_isolates: args.get("remove_isolates").and_then(|v| v.as_bool()).unwrap_or(defaults.remove_isolates),
1157	        max_components: args.get("max_components").and_then(|v| v.as_u64()).map(|v| v as usize).unwrap_or(defaults.max_components),
1158	        required_attrs: args.get("required_attrs").and_then(|v| v.as_array()).map(|arr| {
1159	            arr.iter().filter_map(|v| v.as_str().map(String::from)).collect()
1160	        }),
1161	        merge_parallel_edges: args.get("merge_parallel_edges").and_then(|v| v.as_bool()).unwrap_or(defaults.merge_parallel_edges),
1162	        merge_parallel_edge_properties: args.get("merge_parallel_edge_properties").and_then(|v| v.as_bool()).unwrap_or(defaults.merge_parallel_edge_properties),
1163	        property_merge_strategy: args.get("property_merge_strategy").and_then(|v| v.as_str()).map(String::from).unwrap_or(defaults.property_merge_strategy),
1164	        simplify_tolerance_m: args.get("simplify_tolerance_m").and_then(|v| v.as_f64()).unwrap_or(defaults.simplify_tolerance_m),
1165	        include_polygons: args.get("include_polygons").and_then(|v| v.as_bool()).unwrap_or(defaults.include_polygons),
1166	        include_points: args.get("include_points").and_then(|v| v.as_bool()).unwrap_or(defaults.include_points),
1167	    };
1168	
1169	    tracing::info!("clean: {} -> {} (min_length={}, node_snap={}, max_components={})",
1170	        input, output, options.min_length_m, options.node_snap_m, options.max_components);
1171	
1172	    // Read input GeoJSON
1173	    let input_str = std::fs::read_to_string(&input)
1174	        .map_err(|e| anyhow::anyhow!("Failed to read input file '{}': {}", input, e))?;
1175	    let geojson: geojson::FeatureCollection = serde_json::from_str(&input_str)
1176	        .map_err(|e| anyhow::anyhow!("Failed to parse GeoJSON: {}", e))?;
1177	
1178	    // Run clean pipeline
1179	    let (cleaned, stats, warnings) = clean_geojson(&geojson, &options)
1180	        .map_err(|e| anyhow::anyhow!("Clean pipeline failed: {}", e))?;
1181	
1182	    // Write output
1183	    let output_str = serde_json::to_string_pretty(&cleaned)
1184	        .map_err(|e| anyhow::anyhow!("Failed to serialize output: {}", e))?;
1185	    std::fs::write(&output, &output_str)
1186	        .map_err(|e| anyhow::anyhow!("Failed to write output file '{}': {}", output, e))?;
1187	
1188	    Ok(json!({
1189	        "output_file": output,
1190	        "input_features": stats.input_features,
1191	        "output_features": stats.output_features,
1192	        "invalid_dropped": stats.invalid_dropped,
1193	        "selfloops_removed": stats.selfloops_removed,
1194	        "short_edges_removed": stats.short_edges_removed,
1195	        "nodes_merged": stats.nodes_merged,
1196	        "duplicate_edges_removed": stats.duplicate_edges_removed,
1197	        "incomplete_edges_removed": stats.incomplete_edges_removed,
1198	        "parallel_edges_merged": stats.parallel_edges_merged,
1199	        "isolates_removed": stats.isolates_removed,
1200	        "components_removed": stats.components_removed,
1201	        "total_removed": stats.total_removed(),
1202	        "warnings": warnings,
1203	    }))
1204	}
