1208	async fn handle_vrp_solve(args: &Value) -> Result<Value> {
1209	    let stops_val = args
1210	        .get("stops")
1211	        .and_then(|v| v.as_array())
1212	        .ok_or_else(|| anyhow::anyhow!("Missing 'stops' parameter"))?;
1213	
1214	    if stops_val.is_empty() {
1215	        anyhow::bail!("At least one stop (the depot) is required");
1216	    }
1217	
1218	    let stops: Vec<VRPSolverStop> = stops_val
1219	        .iter()
1220	        .enumerate()
1221	        .map(|(i, s)| {
1222	            let lat = s.get("lat").and_then(|v| v.as_f64())
1223	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lat'", i))?;
1224	            let lon = s.get("lon").and_then(|v| v.as_f64())
