1568	// ── Inspect RMP handler ──────────────────────────────────────────────────
1569	
1570	fn handle_inspect_rmp(args: &Value) -> Result<Value> {
1571	    let input = args
1572	        .get("input")
1573	        .and_then(|v| v.as_str())
1574	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?;
1575	
1576	    let file_data = std::fs::read(input)
1577	        .map_err(|e| anyhow::anyhow!("Failed to read .rmp file: {}", e))?;
1578	
1579	    let (nodes, edges) = v2rmp::core::optimize::read_rmp_file(&file_data)?;
1580	
1581	    // Compute bounding box from nodes
1582	    let (min_lon, min_lat, max_lon, max_lat) = if nodes.is_empty() {
1583	        (0.0, 0.0, 0.0, 0.0)
1584	    } else {
1585	        nodes.iter().fold(
1586	            (f64::MAX, f64::MAX, f64::MIN, f64::MIN),
1587	            |(mn_lon, mn_lat, mx_lon, mx_lat), n| {
1588	                (mn_lon.min(n.lon), mn_lat.min(n.lat), mx_lon.max(n.lon), mx_lat.max(n.lat))
1589	            },
1590	        )
1591	    };
1592	
1593	    let total_edge_length_km: f64 = edges.iter().map(|e| e.weight_m / 1000.0).sum();
1594	
1595	    Ok(json!({
1596	        "node_count": nodes.len(),
1597	        "edge_count": edges.len(),
1598	        "bbox": {
1599	            "min_lat": min_lat,
1600	            "max_lat": max_lat,
1601	            "min_lon": min_lon,
1602	            "max_lon": max_lon,
1603	        },
1604	        "total_edge_length_km": total_edge_length_km,
1605	        "file_size_bytes": file_data.len(),
1606	    }))
1607	}
