2062	        let mut parser = v2rmp::core::nlp::QwenNLParser::new()?;
2063	        let json_str = parser.parse_llm(query)?;
2064	        
2065	        // Try to parse the LLM output as JSON. If it fails, fallback to regex.
2066	        match serde_json::from_str::<Value>(&json_str) {
2067	            Ok(json) => {
