  5	
  6	fn solve(matrix: &DistMatrix, locations: &[VRPSolverStop], num_vehicles: usize) -> SolveResult {
  7	    let n = matrix.len();
  8	    if n <= 1 {
  9	        return SolveResult {
 10	            routes: vec![vec![0]],
 11	            total_distance: 0.0,
 12	            total_time: 0.0,
 13	        };
 14	    }
 15	
 16	    let mut routes = crate::core::vrp::utils::build_sweep_routes(matrix, locations, num_vehicles);
 17	
 18	    // 2-opt improvement per route
 19	    for route in &mut routes {
 20	        let mut improved = true;
 21	        while improved {
 22	            improved = false;
 23	            let r_len = route.len();
 24	            for i in 1..r_len.saturating_sub(1) {
 25	                for k in (i + 1)..r_len {
 26	                    let delta = matrix_get_dist(matrix, route[i - 1], route[k])
 27	                        + matrix_get_dist(matrix, route[i], route[k.min(route.len() - 1)])
 28	                        - matrix_get_dist(matrix, route[i - 1], route[i])
 29	                        - matrix_get_dist(matrix, route[k], route[k.min(route.len() - 1)]);
 30	                    if delta < -1e-9 {
 31	                        route[i..=k].reverse();
 32	                        improved = true;
 33	                    }
 34	                }
 35	            }
 36	        }
 37	    }
 38	
 39	    let final_routes: Vec<Vec<usize>> = routes.into_iter().filter(|r| r.len() > 2).collect();
 40	    if final_routes.is_empty() {
 41	        return SolveResult {
 42	            routes: vec![vec![0, 0]],
 43	            total_distance: 0.0,
 44	            total_time: 0.0,
 45	        };
 46	    }
 47	
 48	    let mut total_distance = 0.0;
 49	    let mut total_time = 0.0;
 50	    for r in &final_routes {
 51	        for i in 0..r.len() - 1 {
 52	            total_distance += matrix_get_dist(matrix, r[i], r[i + 1]);
 53	            total_time += matrix_get_time(matrix, r[i], r[i + 1]);
 54	        }
 55	    }
 56	
 57	    SolveResult {
 58	        routes: final_routes,
 59	        total_distance,
 60	        total_time,
 61	    }
 62	}
