  1	//! Or-Opt: sweep construction + iterative relocation of chains of 1-3
  2	//! consecutive stops to the best position across all routes.
  3	
  4	use super::super::types::*;
  5	use super::super::utils::{matrix_get_dist, matrix_get_time};
  6	
  7	fn solve(matrix: &DistMatrix, locations: &[VRPSolverStop], num_vehicles: usize, balance_load: bool) -> SolveResult {
  8	    let n = matrix.len();
  9	    if n <= 1 {
 10	        return SolveResult {
 11	            routes: vec![vec![0]],
 12	            total_distance: 0.0,
 13	            total_time: 0.0,
 14	        };
 15	    }
 16	
 17	    let mut routes = crate::core::vrp::utils::build_sweep_routes(matrix, locations, num_vehicles);
 18	
 19	    let intermediate_count = |r: &[usize]| -> usize {
 20	        if r.len() > 2 {
 21	            r.len() - 2
 22	        } else {
 23	            0
 24	        }
 25	    };
 26	
 27	    let mut improved = true;
 28	    let max_passes = 100;
 29	    let mut passes = 0;
 30	
 31	    while improved && passes < max_passes {
 32	        improved = false;
 33	        passes += 1;
 34	
 35	        'outer: for ri in 0..routes.len() {
 36	            let route_a_len = routes[ri].len();
 37	            if route_a_len < 3 {
 38	                continue;
 39	            }
 40	
 41	            for k in 1..=3usize {
 42	                for pos in 1..(route_a_len.saturating_sub(k - 1)) {
 43	                    if pos + k > route_a_len - 1 {
 44	                        break;
 45	                    }
 46	                    let chain_first = routes[ri][pos];
 47	                    let chain_last = routes[ri][pos + k - 1];
 48	                    let prev = routes[ri][pos - 1];
 49	                    let next_idx = pos + k;
 50	                    let next = if next_idx < routes[ri].len() {
 51	                        routes[ri][next_idx]
 52	                    } else {
 53	                        routes[ri][0]
 54	                    };
 55	
 56	                    let remove_gain = matrix_get_dist(matrix, prev, chain_first)
 57	                        + matrix_get_dist(matrix, chain_last, next)
 58	                        - matrix_get_dist(matrix, prev, next);
 59	
 60	                    let mut best_gain = 1e-9;
 61	                    let mut best_rj: Option<usize> = None;
 62	                    let mut best_ins: Option<usize> = None;
 63	                    let mut best_rev = false;
 64	
 65	                    for (rj, _) in routes.iter().enumerate() {
 66	                        let route_b_len = routes[rj].len();
 67	                        for ins in 0..route_b_len.saturating_sub(1) {
 68	                            if rj == ri && ins >= pos.saturating_sub(1) && ins < pos + k {
 69	                                continue;
 70	                            }
 71	
 72	                            let a_node = routes[rj][ins];
 73	                            let b_node = if ins + 1 < route_b_len {
 74	                                routes[rj][ins + 1]
 75	                            } else {
 76	                                routes[rj][0]
 77	                            };
 78	
 79	                            let cost_fwd = matrix_get_dist(matrix, a_node, chain_first)
 80	                                + matrix_get_dist(matrix, chain_last, b_node)
 81	                                - matrix_get_dist(matrix, a_node, b_node);
 82	                            if remove_gain - cost_fwd > best_gain {
 83	                                best_gain = remove_gain - cost_fwd;
 84	                                best_rj = Some(rj);
 85	                                best_ins = Some(ins);
 86	                                best_rev = false;
 87	                            }
 88	
 89	                            if k > 1 {
 90	                                let cost_rev = matrix_get_dist(matrix, a_node, chain_last)
 91	                                    + matrix_get_dist(matrix, chain_first, b_node)
 92	                                    - matrix_get_dist(matrix, a_node, b_node);
 93	                                if remove_gain - cost_rev > best_gain {
 94	                                    best_gain = remove_gain - cost_rev;
 95	                                    best_rj = Some(rj);
 96	                                    best_ins = Some(ins);
 97	                                    best_rev = true;
 98	                                }
 99	                            }
100	                        }
101	                    }
102	
103	                    let Some(rj_val) = best_rj else { continue };
104	                    let Some(ins_val) = best_ins else { continue };
105	
106	                    if balance_load && rj_val != ri {
107	                        let new_count_a = intermediate_count(&routes[ri]).saturating_sub(k);
108	                        let new_count_b = intermediate_count(&routes[rj_val]).saturating_add(k);
109	                        let counts: Vec<usize> = routes
110	                            .iter()
111	                            .enumerate()
112	                            .map(|(idx, r)| {
113	                                if idx == ri {
114	                                    new_count_a
115	                                } else if idx == rj_val {
116	                                    new_count_b
117	                                } else {
118	                                    intermediate_count(r)
119	                                }
120	                            })
121	                            .collect();
122	                        let max_c = *counts.iter().max().unwrap_or(&0);
123	                        let min_c = *counts.iter().min().unwrap_or(&0);
124	                        if max_c - min_c > 1 {
125	                            continue;
126	                        }
127	                    }
128	
129	                    improved = true;
130	                    let chain: Vec<usize> = routes[ri][pos..pos + k].to_vec();
131	                    let insert_chain: Vec<usize> = if best_rev {
132	                        chain.iter().copied().rev().collect()
133	                    } else {
134	                        chain.clone()
135	                    };
136	
137	                    if rj_val == ri {
138	                        let mut r = routes[ri].clone();
139	                        r.splice(pos..pos + k, std::iter::empty());
140	                        let adj_ins = if ins_val >= pos { ins_val - k } else { ins_val };
141	                        let insert_at = adj_ins + 1;
142	                        let mut result = r[..insert_at].to_vec();
143	                        result.extend_from_slice(&insert_chain);
144	                        result.extend_from_slice(&r[insert_at..]);
145	                        routes[ri] = result;
146	                    } else {
147	                        let mut r_a = routes[ri].clone();
148	                        r_a.splice(pos..pos + k, std::iter::empty());
149	                        routes[ri] = r_a;
150	                        let r_b = routes[rj_val].clone();
151	                        let insert_at = ins_val + 1;
152	                        let mut result = r_b[..insert_at].to_vec();
153	                        result.extend_from_slice(&insert_chain);
154	                        result.extend_from_slice(&r_b[insert_at..]);
155	                        routes[rj_val] = result;
156	                    }
157	
158	                    break 'outer;
159	                }
160	            }
161	        }
162	    }
163	
164	    let final_routes: Vec<Vec<usize>> = routes.into_iter().filter(|r| r.len() > 2).collect();
165	    if final_routes.is_empty() {
166	        return SolveResult {
167	            routes: vec![vec![0, 0]],
168	            total_distance: 0.0,
169	            total_time: 0.0,
170	        };
171	    }
172	
173	    let mut total_distance = 0.0;
174	    let mut total_time = 0.0;
175	    for r in &final_routes {
176	        for i in 0..r.len() - 1 {
177	            total_distance += matrix_get_dist(matrix, r[i], r[i + 1]);
178	            total_time += matrix_get_time(matrix, r[i], r[i + 1]);
179	        }
180	    }
181	
182	    SolveResult {
183	        routes: final_routes,
184	        total_distance,
185	        total_time,
186	    }
187	}
