191	#[async_trait::async_trait]
192	impl VRPSolver for OrOptSolver {
193	    fn id(&self) -> &str {
194	        "or_opt"
195	    }
196	    fn label(&self) -> &str {
197	        "Or-Opt (local search)"
198	    }
199	    fn requires_matrix(&self) -> bool {
200	        true
201	    }
