203	    async fn solve(&self, input: &VRPSolverInput) -> Result<VRPSolverOutput, String> {
204	        let matrix = input
205	            .matrix
206	            .as_ref()
207	            .ok_or("Or-Opt solver requires a distance matrix")?;
208	        let balance_load = input.objective == VrpObjective::BalanceLoad;
209	        let result = solve(matrix, &input.locations, input.num_vehicles, balance_load);
210	        Ok(result.into_output(input))
211	    }
212	    fn clone_box(&self) -> Box<dyn VRPSolver> {
213	        Box::new(OrOptSolver)
214	    }
215	}
