 59	/// Fetch a real-road distance/time matrix from Valhalla.
 60	pub async fn get_valhalla_matrix(locations: &[VRPSolverStop]) -> Result<DistMatrix, String> {
 61	    let url = "https://valhalla1.openstreetmap.de/sources_to_targets";
 62	    let locs: Vec<serde_json::Value> = locations
 63	        .iter()
 64	        .map(|l| serde_json::json!({"lat": l.lat, "lon": l.lon}))
 65	        .collect();
 66	
 67	    let body = serde_json::json!({
 68	        "sources": locs,
 69	        "targets": locs,
 70	        "costing": "auto",
 71	        "directions_options": { "units": "kilometers" }
 72	    });
 73	
 74	    let client = reqwest::Client::new();
 75	    let resp = client
 76	        .post(url)
 77	        .json(&body)
 78	        .send()
 79	        .await
 80	        .map_err(|e| format!("Valhalla request failed: {e}"))?;
 81	
 82	    if !resp.status().is_success() {
 83	        return Err(format!("Valhalla HTTP {}", resp.status()));
 84	    }
 85	
 86	    let data: serde_json::Value = resp
 87	        .json()
 88	        .await
 89	        .map_err(|e| format!("Valhalla parse error: {e}"))?;
 90	
 91	    let stt = data
 92	        .get("sources_to_targets")
 93	        .ok_or("Invalid Valhalla response: missing sources_to_targets")?;
 94	
 95	    let rows = stt
 96	        .as_array()
 97	        .ok_or("Invalid Valhalla response: sources_to_targets not an array")?;
 98	    let n = rows.len();
 99	    let mut matrix = Vec::with_capacity(n);
100	    for row_val in rows {
101	        let row = row_val.as_array().ok_or("Invalid Valhalla row")?;
102	        let mut matrix_row = Vec::with_capacity(n);
103	        for cell_val in row {
104	            let cell = cell_val.as_object();
105	            let (dist, time) = match cell {
106	                Some(c) => (
107	                    c.get("distance").and_then(|v| v.as_f64()).unwrap_or(0.0),
108	                    c.get("time").and_then(|v| v.as_f64()).unwrap_or(0.0),
109	                ),
110	                None => (0.0, 0.0),
111	            };
112	            matrix_row.push(DistCell {
113	                distance: dist,
114	                time,
115	            });
116	        }
117	        matrix.push(matrix_row);
118	    }
119	    Ok(matrix)
120	}
