122	/// Cluster stops into geographic grid zones so nearby stops are grouped together.
123	pub fn cluster_by_zones(locations: &[VRPSolverStop], num_zones: usize) -> Vec<Vec<usize>> {
124	    let n = locations.len();
125	    if n <= num_zones {
126	        return (0..n).map(|i| vec![i]).collect();
127	    }
128	    let min_lat = locations
129	        .iter()
130	        .map(|p| p.lat)
131	        .fold(f64::INFINITY, f64::min);
132	    let max_lat = locations
133	        .iter()
134	        .map(|p| p.lat)
135	        .fold(f64::NEG_INFINITY, f64::max);
136	    let min_lon = locations
137	        .iter()
138	        .map(|p| p.lon)
139	        .fold(f64::INFINITY, f64::min);
140	    let max_lon = locations
141	        .iter()
142	        .map(|p| p.lon)
143	        .fold(f64::NEG_INFINITY, f64::max);
144	
145	    let rows = (num_zones as f64).sqrt().ceil() as usize;
146	    let cols = num_zones.div_ceil(rows); // ceil division
147	    let cell_lat = (max_lat - min_lat) / rows as f64;
148	    let cell_lon = (max_lon - min_lon) / cols as f64;
149	    let cell_lat = if cell_lat == 0.0 { 0.001 } else { cell_lat };
150	    let cell_lon = if cell_lon == 0.0 { 0.001 } else { cell_lon };
151	
152	    let mut grid: std::collections::BTreeMap<(usize, usize), Vec<usize>> =
153	        std::collections::BTreeMap::new();
154	    for (i, _) in locations.iter().enumerate().take(n) {
155	        let p = &locations[i];
156	        let ri = ((p.lat - min_lat) / cell_lat).floor() as usize;
157	        let ri = ri.min(rows - 1);
158	        let ci = ((p.lon - min_lon) / cell_lon).floor() as usize;
159	        let ci = ci.min(cols - 1);
160	        grid.entry((ri, ci)).or_default().push(i);
161	    }
162	    grid.into_values().collect()
163	}
