165	/// Order clusters so the start zone comes first, then nearest by centroid.
166	pub fn order_clusters_by_start(
167	    clusters: &[Vec<usize>],
168	    locations: &[VRPSolverStop],
169	    start_index: usize,
170	) -> Vec<Vec<usize>> {
171	    let start = &locations[start_index];
172	    let mut with_centroid: Vec<(Vec<usize>, f64, bool)> = clusters
173	        .iter()
174	        .map(|indices| {
175	            let lat: f64 =
176	                indices.iter().map(|&i| locations[i].lat).sum::<f64>() / indices.len() as f64;
177	            let lon: f64 =
178	                indices.iter().map(|&i| locations[i].lon).sum::<f64>() / indices.len() as f64;
179	            let dist = haversine_km(start.lat, start.lon, lat, lon);
180	            let contains_start = indices.contains(&start_index);
181	            (indices.clone(), dist, contains_start)
182	        })
183	        .collect();
184	
185	    with_centroid.sort_by(|a, b| {
186	        if a.2 && !b.2 {
187	            std::cmp::Ordering::Less
188	        } else if !a.2 && b.2 {
189	            std::cmp::Ordering::Greater
190	        } else {
191	            a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal)
192	        }
193	    });
194	
195	    with_centroid
196	        .into_iter()
197	        .map(|(indices, _, _)| indices)
198	        .collect()
199	}
