201	/// Nearest-neighbor TSP construction for a subset of indices.
202	pub fn nearest_neighbor_route(
203	    matrix: &DistMatrix,
204	    indices: &[usize],
205	    start_idx_in_subset: usize,
206	) -> Vec<usize> {
207	    if indices.len() <= 1 {
208	        return indices.to_vec();
209	    }
210	    let mut route = Vec::with_capacity(indices.len());
211	    let mut remaining: std::collections::HashSet<usize> = indices.iter().copied().collect();
212	    let start_global = indices[start_idx_in_subset];
213	    route.push(start_global);
214	    remaining.remove(&start_global);
215	    let mut current = start_global;
216	    while !remaining.is_empty() {
217	        let mut nearest = 0;
218	        let mut best_dist = f64::INFINITY;
219	        for &i in &remaining {
220	            let d = matrix
221	                .get(current)
222	                .and_then(|row| row.get(i))
223	                .map(|c| c.distance)
224	                .unwrap_or(f64::INFINITY);
225	            if d < best_dist {
226	                best_dist = d;
227	                nearest = i;
228	            }
229	        }
230	        route.push(nearest);
231	        remaining.remove(&nearest);
232	        current = nearest;
233	    }
234	    route
235	}
