282	pub fn matrix_get_time(matrix: &DistMatrix, i: usize, j: usize) -> f64 {
283	    matrix
284	        .get(i)
285	        .and_then(|row| row.get(j))
286	        .map(|c| c.time)
287	        .unwrap_or(0.0)
