290	pub fn build_sweep_routes(
291	    matrix: &crate::core::vrp::types::DistMatrix,
292	    locations: &[crate::core::vrp::types::VRPSolverStop],
293	    num_vehicles: usize,
294	) -> Vec<Vec<usize>> {
295	    let n = locations.len();
296	    if n <= 1 {
297	        return vec![];
298	    }
299	    let depot = &locations[0];
300	    let mut indices: Vec<usize> = (1..n).collect();
301	    indices.sort_by(|&a, &b| {
302	        let la = &locations[a];
303	        let lb = &locations[b];
304	        let angle_a = (la.lat - depot.lat).atan2(la.lon - depot.lon);
305	        let angle_b = (lb.lat - depot.lat).atan2(lb.lon - depot.lon);
306	        angle_a.partial_cmp(&angle_b).unwrap_or(std::cmp::Ordering::Equal)
307	    });
308	
309	    let per_route = (indices.len() as f64 / num_vehicles as f64).ceil() as usize;
310	    let mut route_indices: Vec<Vec<usize>> = Vec::new();
311	
312	    for v in 0..num_vehicles {
313	        let start = v * per_route;
314	        let end = std::cmp::min(start + per_route, indices.len());
315	        if start >= indices.len() { break; }
316	        let segment = &indices[start..end];
317	        if segment.is_empty() { continue; }
318	
319	        let mut route = vec![0];
320	        let mut remaining: std::collections::HashSet<usize> = segment.iter().copied().collect();
321	        let mut current = 0;
322	        while !remaining.is_empty() {
323	            let mut best = 0;
324	            let mut best_dist = f64::INFINITY;
325	            for &node in &remaining {
326	                let dist = crate::core::vrp::utils::matrix_get_dist(matrix, current, node);
327	                if dist < best_dist {
328	                    best_dist = dist;
329	                    best = node;
330	                }
331	            }
332	            remaining.remove(&best);
333	            route.push(best);
334	            current = best;
335	        }
336	        route.push(0);
337	        route_indices.push(route);
338	    }
339	    route_indices
340	}
