//! Instance-aware AutoML hyperparameter tuner.
//!
//! Predicts solver hyperparameters from instance features using
//! Ridge regression or a small multi-output MLP.
//!
//! Research basis: Instance-Aware Parameter Configuration (2605.00572, 2026)

use crate::core::ml::features::InstanceFeatures;
use anyhow::{Context, Result};
use candle_core::{Device, DType, Tensor};
use candle_nn::{linear, Linear, Module, VarBuilder};
use serde::{Deserialize, Serialize};
use std::path::Path;

const NUM_FEATURES: usize = 28;
const HIDDEN1: usize = 64;
const NUM_OUTPUTS: usize = 5;

/// Hyperparameters for a VRP solver.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct SolverHyperparams {
    /// Maximum iterations for metaheuristics (e.g. simulated annealing).
    pub max_iterations: u32,
    /// Temperature for simulated annealing.
    pub temperature: f64,
    /// Tabu tenure for tabu search.
    pub tabu_tenure: usize,
    /// Cooling rate for SA.
    pub cooling_rate: f64,
    /// Neighbourhood radius for local search.
    pub neighbourhood_radius: usize,
    /// Whether the learned model was used (true) or fallback defaults (false).
    pub model_used: bool,
}

/// Learned multi-output MLP hyperparameter predictor.
pub struct HyperparamPredictor {
    lin1: Linear,
    lin2: Linear,
    device: Device,
}

impl HyperparamPredictor {
    /// Load from a safetensors file.
    pub fn from_file(path: &Path) -> Result<Self> {
        let device = crate::core::ml::best_device()?;
        let tensors = candle_core::safetensors::load(path, &device)
            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
        let lin1 = linear(NUM_FEATURES, HIDDEN1, vb.pp("lin1"))?;
        let lin2 = linear(HIDDEN1, NUM_OUTPUTS, vb.pp("lin2"))?;
        Ok(Self { lin1, lin2, device })
    }

    /// Predict hyperparameters from instance features.
    pub fn predict(&self, features: &InstanceFeatures) -> Result<SolverHyperparams> {
        let x = features.to_vector();
        let input = Tensor::from_vec(x, (1, NUM_FEATURES), &self.device)?;
        let h1 = self.lin1.forward(&input)?.relu()?;
        let out = self.lin2.forward(&h1)?;
        let vals: Vec<f32> = out.to_vec1()?;
        let v = vals.as_slice();

        // Clamp each output to [0, 1] and scale to parameter range
        let max_iter = (100.0 + v[0].clamp(0.0, 1.0) * 9900.0) as u32;
        let temperature = 1.0 + v[1].clamp(0.0, 1.0) * 999.0;
        let tabu_tenure = (1.0 + v[2].clamp(0.0, 1.0) * 49.0).round() as usize;
        let cooling_rate = 0.8 + v[3].clamp(0.0, 1.0) * 0.199;
        let neighbourhood_radius = (1.0 + v[4].clamp(0.0, 1.0) * 19.0).round() as usize;

        Ok(SolverHyperparams {
            max_iterations: max_iter,
            temperature,
            tabu_tenure,
            cooling_rate,
            neighbourhood_radius,
            model_used: true,
        })
    }
}

/// Default model path relative to the executable.
pub fn default_model_path() -> std::path::PathBuf {
    std::env::current_exe()
        .unwrap_or_else(|_| std::path::PathBuf::from("."))
        .parent()
        .unwrap_or(std::path::Path::new("."))
        .join("models")
        .join("automl.safetensors")
}

/// Predict hyperparameters for a given instance.
///
/// Tries to load the neural model. If missing or failed, falls back to
/// sensible defaults.
pub fn predict_hyperparams(features: &InstanceFeatures) -> SolverHyperparams {
    let path = default_model_path();
    if path.exists() {
        match HyperparamPredictor::from_file(&path) {
            Ok(model) => {
                match model.predict(features) {
                    Ok(params) => return params,
                    Err(e) => {
                        tracing::warn!("Hyperparam predictor inference failed: {}. Falling back to defaults.", e);
                    }
                }
            }
            Err(e) => {
                tracing::warn!("Failed to load hyperparam predictor: {}. Falling back to defaults.", e);
            }
        }
    }
    SolverHyperparams::default_fallback()
}

impl SolverHyperparams {
    /// Sensible defaults tuned on a broad synthetic instance set.
    pub fn default_fallback() -> Self {
        Self {
            max_iterations: 1000,
            temperature: 100.0,
            tabu_tenure: 7,
            cooling_rate: 0.995,
            neighbourhood_radius: 3,
            model_used: false,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core::vrp::test_utils::{make_input, make_stop};

    #[test]
    fn test_predict_hyperparams_fallback() {
        let stops = vec![
            make_stop(0.0, 0.0, "depot"),
            make_stop(1.0, 0.0, "a"),
            make_stop(0.0, 1.0, "b"),
        ];
        let input = make_input(stops, 1);
        let features = InstanceFeatures::from_input(&input);
        let params = predict_hyperparams(&features);
        assert!(params.max_iterations >= 100);
        assert!(params.temperature >= 1.0);
        assert!(params.tabu_tenure >= 1);
        assert!(params.cooling_rate >= 0.8 && params.cooling_rate <= 1.0);
        assert!(params.neighbourhood_radius >= 1);
    }
}

arguments.content:
//! Neural-Guided Local Search Solver.
//!
//! Constructs routes with sweep + nearest-neighbor, then applies neural-guided
//! 2-Opt improvement.  Instead of evaluating all O(n²) swaps exhaustively, a
//! tiny MLP (MoveScorer) scores candidate moves and only the top-k are
//! considered at each iteration.
//!
//! Research basis: RLOR (2303.13117)

use super::super::types::*;
use super::super::utils::{build_sweep_routes, matrix_get_dist};
use anyhow::{Context, Result};
use candle_core::{Device, DType, Tensor};
use candle_nn::{linear, Linear, Module, VarBuilder};
use std::path::Path;

const MOVE_FEATURE_DIM: usize = 16;

/// A tiny MLP to score local-search moves: 16 → 32 → 16 → 1
pub struct MoveScorer {
    lin1: Linear,
    lin2: Linear,
    lin3: Linear,
    device: Device,
}

impl MoveScorer {
    /// Load from a safetensors file.
    pub fn from_file(path: &Path) -> Result<Self> {
        let device = crate::core::ml::best_device()?;
        let tensors = candle_core::safetensors::load(path, &device)
            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);

        let lin1 = linear(MOVE_FEATURE_DIM, 32, vb.pp("lin1"))?;
        let lin2 = linear(32, 16, vb.pp("lin2"))?;
        let lin3 = linear(16, 1, vb.pp("lin3"))?;

        Ok(Self { lin1, lin2, lin3, device })
    }

    /// Predict scores for a batch of moves.
    pub fn score_moves(&self, features: &[f32]) -> Result<Vec<f32>> {
        let num_moves = features.len() / MOVE_FEATURE_DIM;
        if num_moves == 0 {
            return Ok(Vec::new());
        }

        let x = Tensor::from_vec(
            features.to_vec(),
            (num_moves, MOVE_FEATURE_DIM),
            &self.device,
        )?;
        let h1 = self.lin1.forward(&x)?.relu()?;
        let h2 = self.lin2.forward(&h1)?.relu()?;
        let out = self.lin3.forward(&h2)?;

        let scores = out.to_vec2::<f32>()?;
        Ok(scores.into_iter().map(|row| row[0]).collect())
    }
}

/// Compute 16-dim feature vector for a candidate 2-opt move.
///
/// The move reverses the segment `route[i..=j]`, replacing edges
/// (route[i-1], route[i]) and (route[j], route[j+1]) with
/// (route[i-1], route[j]) and (route[i], route[j+1]).
fn move_features(
    route: &[usize],
    i: usize,
    j: usize,
    matrix: &DistMatrix,
    route_total_dist: f64,
) -> [f32; MOVE_FEATURE_DIM] {
    let n = route.len();
    let a = route[i - 1];
    let b = route[i];
    let c = route[j];
    let d = route[(j + 1) % n];

    let d_ab = matrix_get_dist(matrix, a, b);
    let d_cd = matrix_get_dist(matrix, c, d);
    let d_ac = matrix_get_dist(matrix, a, c);
    let d_bd = matrix_get_dist(matrix, b, d);

    let delta = (d_ac + d_bd) - (d_ab + d_cd);

    let avg_edge = if n > 1 {
        route_total_dist / (n - 1) as f64
    } else {
        1.0
    };
    let avg_edge = avg_edge.max(1e-6);

    let seg_len = (i..=j)
        .map(|k| matrix_get_dist(matrix, route[k], route[(k + 1) % n]))
        .sum::<f64>();

    let seg_stops = (j - i + 1) as f64;
    let route_len = n as f64;

    [
        d_ab as f32,
        d_cd as f32,
        d_ac as f32,
        d_bd as f32,
        delta as f32,
        (d_ab / avg_edge) as f32,
        (d_cd / avg_edge) as f32,
        (d_ac / avg_edge) as f32,
        (d_bd / avg_edge) as f32,
        seg_len as f32,
        (seg_len / route_total_dist.max(1e-6)) as f32,
        seg_stops as f32,
        (seg_stops / route_len) as f32,
        (i as f64 / route_len) as f32,
        (j as f64 / route_len) as f32,
        if delta < -1e-6 { 1.0 } else { 0.0 },
    ]
}

/// Generate all candidate 2-opt moves for a route and return (features, (i, j, delta)) pairs.
fn generate_candidates(
    route: &[usize],
    matrix: &DistMatrix,
    route_total_dist: f64,
) -> (Vec<f32>, Vec<(usize, usize, f64)>) {
    let n = route.len();
    let mut features = Vec::new();
    let mut meta = Vec::new();

    if n <= 3 {
        return (features, meta);
    }

    for i in 1..n - 2 {
        for j in (i + 1)..n - 1 {
            let a = route[i - 1];
            let b = route[i];
            let c = route[j];
            let d = route[(j + 1) % n];

            let before = matrix_get_dist(matrix, a, b) + matrix_get_dist(matrix, c, d);
            let after = matrix_get_dist(matrix, a, c) + matrix_get_dist(matrix, b, d);
            let delta = after - before;

            let feats = move_features(route, i, j, matrix, route_total_dist);
            features.extend_from_slice(&feats);
            meta.push((i, j, delta));
        }
    }

    (features, meta)
}

/// Neural-guided 2-Opt improvement for a single route.
fn neural_guided_two_opt(
    route: &mut Vec<usize>,
    matrix: &DistMatrix,
    scorer: Option<&MoveScorer>,
) {
    let n = route.len();
    if n <= 3 {
        return;
    }

    let route_dist = |r: &[usize]| -> f64 {
        (0..r.len() - 1)
            .map(|k| matrix_get_dist(matrix, r[k], r[k + 1]))
            .sum()
    };

    let mut improved = true;
    let max_iter = 300;
    let mut iter = 0;

    while improved && iter < max_iter {
        improved = false;
        iter += 1;

        let total_dist = route_dist(route);
        let (features, meta) = generate_candidates(route, matrix, total_dist);

        if meta.is_empty() {
            break;
        }

        let mut scored: Vec<(usize, f64)> = if let Some(s) = scorer {
            match s.score_moves(&features) {
                Ok(scores) => scores
                    .into_iter()
                    .enumerate()
                    .map(|(idx, score)| (idx, score as f64))
                    .collect(),
                Err(e) => {
                    tracing::warn!("Move scoring failed: {}. Falling back to exhaustive.", e);
                    meta.iter()
                        .enumerate()
                        .map(|(idx, (_, _, delta))| (idx, -delta))
                        .collect()
                }
            }
        } else {
            // No model: score by raw delta (lower is better → negate for ranking)
            meta.iter()
                .enumerate()
                .map(|(idx, (_, _, delta))| (idx, -delta))
                .collect()
        };

        // Sort by score descending (higher score = more promising)
        scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

        // Try top-k candidates; if model is loaded, examine more before giving up
        let top_k = if scorer.is_some() { scored.len().min(50) } else { scored.len().min(1) };

        for &(idx, _) in &scored[..top_k] {
            let (i, j, delta) = meta[idx];
            if delta < -1e-9 {
                route[i..=j].reverse();
                improved = true;
                break; // restart candidate generation
            }
        }
    }
}

fn solve(
    matrix: &DistMatrix,
    locations: &[VRPSolverStop],
    num_vehicles: usize,
) -> SolveResult {
    let n = matrix.len();
    if n <= 1 {
        return SolveResult {
            routes: vec![vec![0]],
            total_distance: 0.0,
            total_time: 0.0,
        };
    }

    let path = default_model_path();
    let scorer = if path.exists() {
        MoveScorer::from_file(&path).ok()
    } else {
        None
    };

    if scorer.is_some() {
        tracing::info!("Neural-guided solver: MoveScorer loaded.");
    } else {
        tracing::info!(
            "Neural-guided solver: MoveScorer not available, falling back to exhaustive 2-opt."
        );
    }

    let mut routes = build_sweep_routes(matrix, locations, num_vehicles);

    for route in &mut routes {
        neural_guided_two_opt(route, matrix, scorer.as_ref());
    }

    let final_routes: Vec<Vec<usize>> = routes.into_iter().filter(|r| r.len() > 2).collect();
    if final_routes.is_empty() {
        return SolveResult {
            routes: vec![vec![0, 0]],
            total_distance: 0.0,
            total_time: 0.0,
        };
    }

    let mut total_distance = 0.0;
    let mut total_time = 0.0;
    for r in &final_routes {
        for i in 0..r.len() - 1 {
            total_distance += matrix_get_dist(matrix, r[i], r[i + 1]);
            total_time += matrix
                .get(r[i])
                .and_then(|row| row.get(r[i + 1]))
                .map(|c| c.time)
                .unwrap_or(0.0);
        }
    }

    SolveResult {
        routes: final_routes,
        total_distance,
        total_time,
    }
}

pub fn default_model_path() -> std::path::PathBuf {
    std::env::current_exe()
        .unwrap_or_else(|_| std::path::PathBuf::from("."))
        .parent()
        .unwrap_or(std::path::Path::new("."))
        .join("models")
        .join("move_scorer.safetensors")
}

pub struct NeuralGuidedSolver;

#[async_trait::async_trait]
impl VRPSolver for NeuralGuidedSolver {
    fn id(&self) -> &str {
        "neural_guided"
    }

    fn label(&self) -> &str {
        "Neural-Guided 2-Opt"
    }

    fn requires_matrix(&self) -> bool {
        true
    }

    async fn solve(&self, input: &VRPSolverInput) -> Result<VRPSolverOutput, String> {
        let matrix = input
            .matrix
            .as_ref()
            .ok_or("Neural-guided solver requires a distance matrix")?;
        let result = solve(matrix, &input.locations, input.num_vehicles);
        Ok(result.into_output(input))
    }

    fn clone_box(&self) -> Box<dyn VRPSolver> {
        Box::new(NeuralGuidedSolver)
    }
}

#[cfg(test)]
mod tests {
    use crate::core::vrp::test_utils::{make_input, make_stop};
    use super::*;

    #[tokio::test]
    async fn test_neural_guided_single_depot() {
        let stops = vec![make_stop(0.0, 0.0, "depot")];
        let input = make_input(stops, 1);
        let solver = NeuralGuidedSolver;
        let output = solver.solve(&input).await.unwrap();
        assert!(output.routes.is_some());
    }

    #[tokio::test]
    async fn test_neural_guided_metadata() {
        let solver = NeuralGuidedSolver;
        assert_eq!(solver.id(), "neural_guided");
        assert!(solver.requires_matrix());
    }

    #[tokio::test]
    async fn test_neural_guided_no_matrix_error() {
        let stops = vec![make_stop(0.0, 0.0, "depot"), make_stop(1.0, 0.0, "a")];
        let input = VRPSolverInput {
            locations: stops,
            num_vehicles: 1,
            vehicle_capacity: 100.0,
            objective: VrpObjective::MinDistance,
            matrix: None,
            service_time_secs: None,
            use_time_windows: false,
            window_open: None,
            window_close: None,
        };
        let solver = NeuralGuidedSolver;
        let err = solver.solve(&input).await.unwrap_err();
        assert!(err.contains("requires a distance matrix"));
    }

    #[tokio::test]
    async fn test_neural_guided_crossing() {
        // A crossing that 2-opt should fix
        let stops = vec![
            make_stop(0.0, 0.0, "depot"),
            make_stop(1.0, 0.0, "a"),
            make_stop(2.0, 0.0, "b"),
            make_stop(3.0, 0.0, "c"),
            make_stop(4.0, 0.0, "d"),
        ];
        let input = make_input(stops.clone(), 1);
        let solver = NeuralGuidedSolver;
        let output = solver.solve(&input).await.unwrap();
        let dist: f64 = output.total_distance_km.parse().unwrap();
        assert!(dist > 0.0);
    }
}

